(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,5896,a=>{"use strict";let e=[{id:"shi-sentences",band:"1",fn:"describing",pattern:"A + 是 + B",title:{en:"'是' (shì) sentences — A is B",id:"Kalimat '是' (shì) — A adalah B"},explanation:{en:"是 (shì, 'to be') links two nouns to say A is B — for identity, names, nationality, or category. Unlike English, Chinese doesn't conjugate 是 for tense or person, and adjectives never take 是 (那本书是新的 is wrong for 'that book is new' — use 是...的 or drop 是 entirely, see the 的 point). Negate with 不是, and ask yes/no questions by adding 吗 at the end.",id:"是 (shì, 'adalah') menghubungkan dua kata benda untuk menyatakan A adalah B — untuk identitas, nama, kewarganegaraan, atau kategori. Berbeda dengan bahasa Indonesia atau Inggris, 是 tidak pernah berubah bentuk menurut waktu atau orang. Kata sifat tidak memakai 是 langsung (是 hanya menghubungkan dua kata benda). Negasikan dengan 不是, dan buat pertanyaan ya/tidak dengan menambahkan 吗 di akhir kalimat."},examples:[{s:"我是老师。",p:"wǒ shì lǎo shī",en:"I am a teacher.",id:"Saya adalah guru."},{s:"他是我朋友。",p:"tā shì wǒ péng you",en:"He is my friend.",id:"Dia adalah teman saya."},{s:"这是我的猫。",p:"zhè shì wǒ de māo",en:"This is my cat.",id:"Ini adalah kucing saya."}],mistake:{wrong:"我是很忙。",right:"我很忙。",note:{en:"是 links two nouns, not a subject and an adjective. To describe how someone/something is, drop 是 and use an adverb like 很 before the adjective instead: 我很忙 (I am busy), not 我是很忙.",id:"是 hanya menghubungkan dua kata benda, bukan subjek dengan kata sifat. Untuk menjelaskan keadaan seseorang/sesuatu, hilangkan 是 dan gunakan kata keterangan seperti 很 sebelum kata sifat: 我很忙 (Saya sibuk), bukan 我是很忙."}}},{id:"ma-questions",band:"1",fn:"questions",pattern:"... + 吗？",title:{en:"吗 (ma) yes/no questions",id:"Pertanyaan ya/tidak dengan 吗"},explanation:{en:"Turn any statement into a yes/no question by adding 吗 at the very end — the word order of the statement never changes. Answer by repeating the verb (是 → 是 / 不是, 有 → 有 / 没有) rather than a plain 'yes' or 'no'.",id:"Ubah kalimat pernyataan apa pun menjadi pertanyaan ya/tidak dengan menambahkan 吗 di akhir kalimat — urutan katanya tidak berubah sama sekali. Jawabannya bukan 'ya' atau 'tidak' polos, melainkan mengulang kata kerjanya (是 → 是 / 不是, 有 → 有 / 没有)."},examples:[{s:"你是学生吗？",p:"nǐ shì xué sheng ma",en:"Are you a student?",id:"Apakah kamu murid?"},{s:"你忙吗？",p:"nǐ máng ma",en:"Are you busy?",id:"Apakah kamu sibuk?"},{s:"他有车吗？",p:"tā yǒu chē ma",en:"Does he have a car?",id:"Apakah dia punya mobil?"}],mistake:{wrong:"你是吗学生？",right:"你是学生吗？",note:{en:"吗 always sits at the very end of the sentence, never in the middle where 是 or the verb was. The statement's word order stays untouched — 吗 is just appended.",id:"吗 selalu diletakkan di akhir kalimat, tidak pernah di tengah menggantikan posisi 是 atau kata kerja. Urutan kata pada kalimat pernyataan tetap sama — 吗 hanya ditambahkan di akhir."}}},{id:"ne-followup",band:"1",fn:"questions",pattern:"A + ne? / Noun + 呢？",title:{en:"呢 (ne) follow-up questions",id:"Pertanyaan lanjutan dengan 呢"},explanation:{en:"After answering a question about yourself, use Noun + 呢? to throw the same question back — it means 'and ~?' / 'what about ~?' without repeating the whole sentence. 呢 can also follow a noun on its own to ask 'where is ~?' when the location is obvious from context, e.g. 我的手机呢? (Where's my phone?).",id:"Setelah menjawab pertanyaan tentang dirimu, gunakan Kata benda + 呢? untuk melempar pertanyaan yang sama — artinya 'kalau ~?' / 'bagaimana dengan ~?' tanpa mengulang seluruh kalimat. 呢 juga bisa ditempel setelah kata benda saja untuk bertanya 'di mana ~?' ketika konteksnya sudah jelas, misalnya 我的手机呢? (Ponsel saya mana?)."},examples:[{s:"我很好，你呢？",p:"wǒ hěn hǎo, nǐ ne",en:"I'm good, and you?",id:"Saya baik, kalau kamu?"},{s:"我喝茶，你呢？",p:"wǒ hē chá, nǐ ne",en:"I'm drinking tea, what about you?",id:"Saya minum teh, kamu bagaimana?"},{s:"妈妈呢？",p:"mā ma ne",en:"Where's Mom?",id:"Ibu di mana?"}]},{id:"negation-bu-mei",band:"1",fn:"past",pattern:"不 vs 没",title:{en:"Negation: 不 (bù) vs 没 (méi)",id:"Negasi: 不 (bù) vs 没 (méi)"},explanation:{en:"不 negates habits, opinions, states, and the future/present in general (我不吃辣 — I don't eat spicy food; 我不去 — I'm not going). 没(有) negates the past — that something didn't happen or doesn't exist right now — and is the only negation used with 有: 我没有钱 (I don't have money), 我昨天没去 (I didn't go yesterday). Never say 不有 — always 没有.",id:"不 dipakai untuk menegasikan kebiasaan, pendapat, keadaan umum, serta hal yang belum/tidak akan terjadi (我不吃辣 — Saya tidak makan pedas; 我不去 — Saya tidak pergi). 没(有) dipakai untuk menegasikan hal di masa lalu — sesuatu yang tidak terjadi atau tidak ada sekarang — dan merupakan satu-satunya negasi yang dipasangkan dengan 有: 我没有钱 (Saya tidak punya uang), 我昨天没去 (Saya kemarin tidak pergi). Jangan pernah mengatakan 不有 — selalu gunakan 没有."},examples:[{s:"我不喜欢咖啡。",p:"wǒ bù xǐ huan kā fēi",en:"I don't like coffee.",id:"Saya tidak suka kopi."},{s:"他没有姐姐。",p:"tā méi yǒu jiě jie",en:"He doesn't have an older sister.",id:"Dia tidak punya kakak perempuan."},{s:"昨天我没吃早饭。",p:"zuó tiān wǒ méi chī zǎo fàn",en:"I didn't eat breakfast yesterday.",id:"Kemarin saya tidak makan sarapan."}],mistake:{wrong:"我不有钱。",right:"我没有钱。",note:{en:"有 (to have) can only be negated with 没, never 不. Say 没有, not 不有.",id:"有 (memiliki) hanya bisa dinegasikan dengan 没, tidak pernah dengan 不. Katakan 没有, bukan 不有."}}},{id:"de-possession",band:"1",fn:"describing",pattern:"Noun/Pronoun + 的 + Noun",title:{en:"的 (de) — possession",id:"的 (de) — kepemilikan"},explanation:{en:"的 works like 's/'of' — put it between the owner and the thing owned: 我的书 (my book), 老师的车 (the teacher's car). For close relationships and small social groups (family, close friends, one's own school/company) 的 is often dropped: 我妈妈 not 我的妈妈, 我们学校 not 我们的学校.",id:"的 berfungsi seperti '-nya' atau 'milik' — letakkan di antara pemilik dan benda yang dimiliki: 我的书 (buku saya), 老师的车 (mobil gurunya). Untuk hubungan dekat dan kelompok sosial kecil (keluarga, teman dekat, sekolah/perusahaan sendiri) 的 sering dihilangkan: 我妈妈 bukan 我的妈妈, 我们学校 bukan 我们的学校."},examples:[{s:"这是我的书。",p:"zhè shì wǒ de shū",en:"This is my book.",id:"Ini buku saya."},{s:"他的名字叫小明。",p:"tā de míng zi jiào xiǎo míng",en:"His name is Xiaoming.",id:"Namanya Xiaoming."},{s:"我爸爸是医生。",p:"wǒ bà ba shì yī shēng",en:"My dad is a doctor.",id:"Ayah saya seorang dokter."}],mistake:{wrong:"我的爸爸是医生。",right:"我爸爸是医生。",note:{en:"的 is usually dropped before close family terms — 我爸爸, 我妈妈, 我哥哥, etc. Keeping 的 isn't grammatically wrong, but it sounds unnaturally distant, like 'the father belonging to me'.",id:"的 biasanya dihilangkan sebelum sebutan keluarga dekat — 我爸爸, 我妈妈, 我哥哥, dan sebagainya. Memakai 的 di sini tidak salah secara tata bahasa, tapi terdengar aneh dan berjarak, seperti 'ayah yang menjadi milik saya'."}}},{id:"measure-word-ge",band:"1",fn:"describing",pattern:"Number + 个 + Noun",title:{en:"Measure word 个 (gè) with numbers",id:"Kata penggolong 个 (gè) dengan angka"},explanation:{en:"Chinese nouns need a measure word between a number and the noun — you can't say 三书 for 'three books'; you need 三本书. 个 is the default, all-purpose measure word, used for people and many everyday objects when you don't know or don't need the specific one: 一个人 (one person), 两个苹果 (two apples). Note: 'two' before a measure word is 两 (liǎng), not 二 (èr) — 两个, not 二个.",id:"Kata benda dalam bahasa Mandarin butuh kata penggolong di antara angka dan kata bendanya — tidak bisa mengatakan 三书 untuk 'tiga buku'; harus 三本书. 个 adalah kata penggolong serbaguna yang paling umum, dipakai untuk orang dan banyak benda sehari-hari saat penggolong khususnya tidak diketahui atau tidak diperlukan: 一个人 (satu orang), 两个苹果 (dua apel). Catatan: 'dua' sebelum kata penggolong memakai 两 (liǎng), bukan 二 (èr) — 两个, bukan 二个."},examples:[{s:"我有两个哥哥。",p:"wǒ yǒu liǎng ge gē ge",en:"I have two older brothers.",id:"Saya punya dua kakak laki-laki."},{s:"桌子上有三个苹果。",p:"zhuō zi shàng yǒu sān ge píng guǒ",en:"There are three apples on the table.",id:"Ada tiga apel di atas meja."},{s:"这个人是谁？",p:"zhè ge rén shì shéi",en:"Who is this person?",id:"Orang ini siapa?"}],mistake:{wrong:"我有二个朋友。",right:"我有两个朋友。",note:{en:"Before a measure word, 'two' is always 两 (liǎng), never 二 (èr) — 二 is only used in counting itself (一, 二, 三...) or numbers like 二十 (twenty).",id:"Sebelum kata penggolong, 'dua' selalu memakai 两 (liǎng), tidak pernah 二 (èr) — 二 hanya dipakai saat menghitung berurutan (一, 二, 三...) atau dalam angka seperti 二十 (dua puluh)."}}},{id:"zai-location",band:"1",fn:"describing",pattern:"Subject + 在 + Place",title:{en:"在 (zài) — location sentences",id:"在 (zài) — kalimat lokasi"},explanation:{en:"在 means 'to be at/in' a place: 我在家 (I'm at home). It can also come before a verb to mean 'in/at [place], [do something]': 我在学校学习 (I study at school). Don't confuse it with 是 — 在 is for location, 是 is for identity.",id:"在 berarti 'berada di' suatu tempat: 我在家 (Saya di rumah). 在 juga bisa diletakkan sebelum kata kerja untuk berarti 'di [tempat], [melakukan sesuatu]': 我在学校学习 (Saya belajar di sekolah). Jangan tertukar dengan 是 — 在 untuk lokasi, 是 untuk identitas."},examples:[{s:"我在家。",p:"wǒ zài jiā",en:"I'm at home.",id:"Saya di rumah."},{s:"他在中国工作。",p:"tā zài zhōng guó gōng zuò",en:"He works in China.",id:"Dia bekerja di Tiongkok."},{s:"书在桌子上。",p:"shū zài zhuō zi shàng",en:"The book is on the table.",id:"Buku itu ada di atas meja."}]},{id:"you-existence",band:"1",fn:"describing",pattern:"Subject + 有 + Noun / Place + 有 + Noun",title:{en:"有 (yǒu) — possession & existence",id:"有 (yǒu) — kepemilikan & keberadaan"},explanation:{en:"有 means 'to have' when the subject is a person (我有一只猫 — I have a cat) and 'there is/are' when the subject is a place (房间里有一张床 — there is a bed in the room). Negate only with 没有, never 不有, and note there's no 是 needed alongside it.",id:"有 berarti 'memiliki' ketika subjeknya orang (我有一只猫 — Saya punya kucing) dan 'ada' ketika subjeknya tempat (房间里有一张床 — Ada sebuah kasur di kamar). Negasikan hanya dengan 没有, tidak pernah dengan 不有, dan tidak perlu 是 di sampingnya."},examples:[{s:"我有一个妹妹。",p:"wǒ yǒu yí ge mèi mei",en:"I have a younger sister.",id:"Saya punya adik perempuan."},{s:"教室里有很多学生。",p:"jiào shì lǐ yǒu hěn duō xué sheng",en:"There are many students in the classroom.",id:"Ada banyak murid di dalam kelas."},{s:"你有时间吗？",p:"nǐ yǒu shí jiān ma",en:"Do you have time?",id:"Apakah kamu punya waktu?"}]},{id:"ye-dou-order",band:"1",fn:"connecting",pattern:"Subject + 也/都 + Verb/Adjective",title:{en:"Adverbs 也 (also) and 都 (all) — and their order",id:"Kata keterangan 也 (juga) dan 都 (semua) — serta urutannya"},explanation:{en:"也 ('also') and 都 ('all/both') are adverbs that always go right before the verb or adjective, never before the subject and never after the verb. When a sentence needs both, the order is fixed: 也 comes before 都 — 我们也都是学生 (we are also all students). Both apply to the subject that comes before them, so word order changes the meaning: 他也很忙 (he is also busy) vs 也他很忙 is simply wrong.",id:"也 ('juga') dan 都 ('semua') adalah kata keterangan yang selalu diletakkan tepat sebelum kata kerja atau kata sifat, tidak pernah sebelum subjek dan tidak pernah setelah kata kerja. Kalau kalimat butuh keduanya, urutannya tetap: 也 selalu sebelum 都 — 我们也都是学生 (kami juga semuanya murid). Keduanya berlaku untuk subjek yang berada sebelum mereka, jadi urutan kata memengaruhi arti: 他也很忙 (dia juga sibuk), sedangkan 也他很忙 salah sama sekali."},examples:[{s:"我也是学生。",p:"wǒ yě shì xué sheng",en:"I'm also a student.",id:"Saya juga murid."},{s:"我们都喜欢中国菜。",p:"wǒ men dōu xǐ huan zhōng guó cài",en:"We all like Chinese food.",id:"Kami semua suka masakan Tiongkok."},{s:"他们也都很累。",p:"tā men yě dōu hěn lèi",en:"They are also all tired.",id:"Mereka juga semuanya lelah."}],mistake:{wrong:"我都也是学生。",right:"我也都是学生。",note:{en:"When 也 and 都 appear together, 也 always comes first: 也都, never 都也.",id:"Ketika 也 dan 都 dipakai bersama, 也 selalu diletakkan lebih dulu: 也都, bukan 都也."}}},{id:"ye-adverb",band:"1",fn:"connecting",pattern:"Subject + 也 + Verb/Adjective",title:{en:"也 (also) goes before the verb",id:"也 (juga) diletakkan sebelum kata kerja"},explanation:{en:"也 means 'also' and sits directly before the verb or adjective — never at the start of the sentence, and never after the verb. English puts 'too' at the end; Chinese never does. It always refers back to the subject in front of it, so 我也学习 is 'I study too', not 'I also study (as well as doing other things)'.",id:"也 berarti 'juga' dan diletakkan tepat sebelum kata kerja atau kata sifat — tidak pernah di awal kalimat, dan tidak pernah setelah kata kerja. Bahasa Indonesia bisa menaruh 'juga' di akhir; bahasa Mandarin tidak. 也 selalu merujuk pada subjek di depannya, jadi 我也学习 berarti 'saya juga belajar'."},examples:[{s:"我也是学生。",p:"wǒ yě shì xué sheng",en:"I'm a student too.",id:"Saya juga murid."},{s:"我也喜欢学习。",p:"wǒ yě xǐ huan xué xí",en:"I like studying too.",id:"Saya juga suka belajar."},{s:"他也看电视。",p:"tā yě kàn diàn shì",en:"He watches TV too.",id:"Dia juga menonton televisi."}],mistake:{wrong:"我是学生也。",right:"我也是学生。",note:{en:"也 cannot go at the end of the sentence the way English 'too' can.",id:"也 tidak boleh diletakkan di akhir kalimat seperti 'juga' dalam bahasa Indonesia."}}},{id:"dou-adverb",band:"1",fn:"connecting",pattern:"Subject + 都 + Verb/Adjective",title:{en:"都 (all) goes before the verb",id:"都 (semua) diletakkan sebelum kata kerja"},explanation:{en:"都 means 'all' or 'both' and, like 也, sits directly before the verb or adjective. It refers back to whatever comes before it, so the plural thing must be mentioned first: 这些东西都很漂亮 ('these things are all lovely'), never 都这些东西很漂亮.",id:"都 berarti 'semua' dan, seperti 也, diletakkan tepat sebelum kata kerja atau kata sifat. 都 merujuk pada apa pun yang disebut sebelumnya, jadi hal yang jamak harus disebut lebih dulu: 这些东西都很漂亮 ('barang-barang ini semuanya bagus'), bukan 都这些东西很漂亮."},examples:[{s:"我们都是学生。",p:"wǒ men dōu shì xué sheng",en:"We are all students.",id:"Kami semua murid."},{s:"这些东西都很漂亮。",p:"zhè xiē dōng xi dōu hěn piào liang",en:"These things are all lovely.",id:"Barang-barang ini semuanya bagus."},{s:"苹果和衣服都不少。",p:"píng guǒ hé yī fu dōu bù shǎo",en:"There are plenty of both apples and clothes.",id:"Apel dan baju keduanya banyak."}],mistake:{wrong:"都我们是学生。",right:"我们都是学生。",note:{en:"都 follows the subject; it never opens the sentence.",id:"都 mengikuti subjek; tidak pernah membuka kalimat."}}},{id:"le-completed-action",band:"1",fn:"past",pattern:"Verb + 了 (+ Object)",title:{en:"了 (le) — completed action",id:"了 (le) — tindakan yang selesai"},explanation:{en:"了 placed right after an action verb presents that event as completed: 我吃了 (I ate / I've eaten). It is not a past-tense form of the verb; a time word tells you when. With an object, the lesson pattern is Verb + 了 + Object: 我买了两本书 (I bought two books). Negate a completed action with 没(有), and drop 了 entirely: 我没吃 (I didn't eat), never 我没吃了.",id:"了 yang diletakkan tepat setelah kata kerja tindakan menyatakan peristiwa itu selesai: 我吃了 (Saya sudah makan). 了 bukan bentuk lampau kata kerja; kata waktu menyatakan kapan. Dengan objek, pola pelajaran ini adalah Kata kerja + 了 + Objek: 我买了两本书 (Saya membeli dua buku). Negasikan tindakan yang selesai dengan 没(有), dan hilangkan 了 sepenuhnya: 我没吃 (Saya belum makan), jangan pernah 我没吃了."},examples:[{s:"我吃了。",p:"wǒ chī le",en:"I've eaten.",id:"Saya sudah makan."},{s:"他买了一件衣服。",p:"tā mǎi le yí jiàn yī fu",en:"He bought a piece of clothing.",id:"Dia membeli sepotong baju."},{s:"我们看了电影。",p:"wǒ men kàn le diàn yǐng",en:"We watched a movie.",id:"Kami menonton film."}],mistake:{wrong:"我没吃了饭。",right:"我没吃饭。",note:{en:"了 and 没(有) don't appear together — 没 already signals that the action didn't happen, so 了 is dropped entirely in the negative.",id:"了 dan 没(有) tidak pernah dipakai bersamaan — 没 sudah menandakan bahwa tindakan itu tidak terjadi, jadi 了 dihilangkan sepenuhnya dalam kalimat negatif."}}},{id:"xiang-vs-yao",band:"1",fn:"ability",pattern:"想 vs 要 + Verb",title:{en:"想 (xiǎng) vs 要 (yào) — want to vs will/need to",id:"想 (xiǎng) vs 要 (yào) — ingin vs mau/perlu"},explanation:{en:"Both sit before a verb, but 想 expresses a wish or desire — softer, like 'I feel like ~ing': 我想睡觉 (I feel like sleeping / I'd like to sleep). 要 is stronger — a firm intention, plan, or need: 我要去北京 (I'm going to Beijing / I need to go to Beijing). Negate 想 with 不想 (don't feel like), but negate 要 with 不想 as well in most everyday contexts — 不要 exists but usually means 'don't!' as a command, so beginners should avoid 不要 for 'I don't want to'.",id:"Keduanya diletakkan sebelum kata kerja, tapi 想 mengungkapkan keinginan atau hasrat — lebih lembut, seperti 'ingin ~': 我想睡觉 (Saya ingin tidur). 要 lebih kuat — niat, rencana, atau kebutuhan yang pasti: 我要去北京 (Saya akan/harus pergi ke Beijing). Negasikan 想 dengan 不想 (tidak ingin). 要 juga biasanya dinegasikan dengan 不想 dalam percakapan sehari-hari — 不要 memang ada, tapi biasanya berarti 'jangan!' sebagai perintah, jadi pemula sebaiknya menghindari 不要 untuk menyatakan 'saya tidak mau'."},examples:[{s:"我想喝水。",p:"wǒ xiǎng hē shuǐ",en:"I feel like drinking water.",id:"Saya ingin minum air."},{s:"我要去医院。",p:"wǒ yào qù yī yuàn",en:"I need to go to the hospital.",id:"Saya harus pergi ke rumah sakit."},{s:"你想吃什么？",p:"nǐ xiǎng chī shén me",en:"What would you like to eat?",id:"Kamu ingin makan apa?"}]},{id:"hui-neng-keyi",band:"1",fn:"ability",pattern:"会 vs 能 vs 可以 + Verb",title:{en:"会 (huì) vs 能 (néng) vs 可以 (kěyǐ) — three kinds of 'can'",id:"会 (huì) vs 能 (néng) vs 可以 (kěyǐ) — tiga jenis 'bisa'"},explanation:{en:"会 = know how to, a learned skill: 我会说汉语 (I can [know how to] speak Chinese). 能 = physically/practically able to, given circumstances: 我今天不能来 (I can't come today [I'm busy/sick]). 可以 = allowed to, permission: 我可以进来吗？(May I come in?). They overlap in casual speech, but for HSK 1 the safest rule: skills → 会, ability/circumstance → 能, permission → 可以.",id:"会 = bisa karena sudah dipelajari, suatu keterampilan: 我会说汉语 (Saya bisa [tahu cara] berbicara Mandarin). 能 = mampu secara fisik/keadaan saat itu: 我今天不能来 (Saya tidak bisa datang hari ini [sibuk/sakit]). 可以 = diizinkan, meminta izin: 我可以进来吗？(Bolehkah saya masuk?). Ketiganya kadang tumpang tindih dalam percakapan santai, tapi untuk HSK 1 aturan paling aman: keterampilan → 会, kemampuan/keadaan → 能, izin → 可以."},examples:[{s:"我会游泳。",p:"wǒ huì yóu yǒng",en:"I know how to swim.",id:"Saya bisa berenang."},{s:"我今天很忙，不能去。",p:"wǒ jīn tiān hěn máng, bù néng qù",en:"I'm very busy today, I can't go.",id:"Saya sangat sibuk hari ini, tidak bisa pergi."},{s:"这里可以拍照吗？",p:"zhè lǐ kě yǐ pāi zhào ma",en:"Can I take photos here?",id:"Bolehkah berfoto di sini?"}],mistake:{wrong:"我不会来，因为我生病了。",right:"我不能来，因为我生病了。",note:{en:"Being unable to come due to circumstances (sickness, being busy) uses 不能, not 不会 — 不会 would mean you never learned how to come, which doesn't make sense here.",id:"Tidak bisa datang karena keadaan (sakit, sibuk) memakai 不能, bukan 不会 — 不会 berarti kamu tidak pernah belajar cara 'datang', yang tidak masuk akal di sini."}}},{id:"yidianr-vs-youdianr",band:"1",fn:"describing",pattern:"一点儿 vs 有点儿",title:{en:"一点儿 (yìdiǎnr) vs 有点儿 (yǒudiǎnr) — 'a bit'",id:"一点儿 (yìdiǎnr) vs 有点儿 (yǒudiǎnr) — 'sedikit'"},explanation:{en:"一点儿 goes AFTER an adjective or verb and is usually neutral or a mild request/comparison: 便宜一点儿 (a bit cheaper), 我喝一点儿水 (I'll drink a bit of water). 有点儿 goes BEFORE an adjective and almost always carries a negative or unwanted nuance: 这个有点儿贵 (this is a bit [too] expensive), 我有点儿累 (I'm a bit tired [and not happy about it]). A quick test: if it sounds like a complaint, it's 有点儿 + adjective; if it's comparing or softening a request, it's adjective/verb + 一点儿.",id:"一点儿 diletakkan SETELAH kata sifat atau kata kerja dan biasanya bernada netral atau permintaan/perbandingan ringan: 便宜一点儿 (sedikit lebih murah), 我喝一点儿水 (Saya minum sedikit air). 有点儿 diletakkan SEBELUM kata sifat dan hampir selalu membawa nuansa negatif atau tidak diinginkan: 这个有点儿贵 (ini agak [terlalu] mahal), 我有点儿累 (Saya agak lelah [dan tidak senang soal itu]). Tes cepat: kalau terdengar seperti keluhan, pakai 有点儿 + kata sifat; kalau sedang membandingkan atau memperhalus permintaan, pakai kata sifat/kata kerja + 一点儿."},examples:[{s:"请说慢一点儿。",p:"qǐng shuō màn yì diǎnr",en:"Please speak a bit more slowly.",id:"Tolong bicara agak pelan."},{s:"这件衣服有点儿小。",p:"zhè jiàn yī fu yǒu diǎnr xiǎo",en:"This piece of clothing is a bit small.",id:"Baju ini agak kekecilan."},{s:"今天天气有点儿冷。",p:"jīn tiān tiān qì yǒu diǎnr lěng",en:"The weather is a bit cold today.",id:"Cuaca hari ini agak dingin."}],mistake:{wrong:"这个有点儿便宜一点儿。",right:"这个便宜一点儿。 / 这个有点儿贵。",note:{en:"Don't mix the two patterns in one sentence. Pick one: adjective + 一点儿 for a neutral comparison/request, or 有点儿 + adjective for a complaint-flavored description.",id:"Jangan mencampur kedua pola dalam satu kalimat. Pilih salah satu: kata sifat + 一点儿 untuk perbandingan/permintaan netral, atau 有点儿 + kata sifat untuk deskripsi bernada keluhan."}}},{id:"question-words",band:"1",fn:"questions",pattern:"什么 / 谁 / 哪儿 / 几",title:{en:"Question words: 什么, 谁, 哪儿, 几",id:"Kata tanya: 什么, 谁, 哪儿, 几"},explanation:{en:"Chinese question words stay right in the slot where the answer would go — no moving them to the front like English. 什么 (what) — 你叫什么名字? (What's your name?). 谁 (who) — 那是谁? (Who is that?). 哪儿 (where) — 你在哪儿? (Where are you?). 几 (how many, for small expected numbers, usually under ~10, and always followed by a measure word) — 你家有几个人? (How many people are in your family?). No question mark word is needed together with 吗 — a sentence with 什么/谁/哪儿/几 already is a question by itself.",id:"Kata tanya dalam bahasa Mandarin tetap berada di posisi tempat jawabannya akan muncul — tidak dipindah ke depan kalimat seperti dalam bahasa Inggris. 什么 (apa) — 你叫什么名字? (Siapa namamu? / secara harfiah: nama apa). 谁 (siapa) — 那是谁? (Itu siapa?). 哪儿 (di mana) — 你在哪儿? (Kamu di mana?). 几 (berapa, untuk jumlah kecil yang diperkirakan, biasanya di bawah ~10, dan selalu diikuti kata penggolong) — 你家有几个人? (Keluargamu ada berapa orang?). Kata tanya seperti ini tidak perlu digabung dengan 吗 — kalimat yang sudah mengandung 什么/谁/哪儿/几 otomatis menjadi kalimat tanya."},examples:[{s:"你喜欢什么运动？",p:"nǐ xǐ huan shén me yùn dòng",en:"What sport do you like?",id:"Kamu suka olahraga apa?"},{s:"他是谁？",p:"tā shì shéi",en:"Who is he?",id:"Dia siapa?"},{s:"洗手间在哪儿？",p:"xǐ shǒu jiān zài nǎr",en:"Where is the bathroom?",id:"Kamar mandi di mana?"}],mistake:{wrong:"什么你喜欢吃？",right:"你喜欢吃什么？",note:{en:"Question words fill the position the answer would occupy — 什么 goes where 'it' (the thing eaten) would go, at the end near the verb, not moved to the front of the sentence.",id:"Kata tanya menempati posisi yang akan diisi oleh jawabannya — 什么 diletakkan di tempat 'benda yang dimakan' seharusnya berada, dekat kata kerja di bagian akhir, bukan dipindah ke depan kalimat."}}},{id:"age-duoda",band:"1",fn:"questions",pattern:"多大 / 几岁 + Number + 岁",title:{en:"Asking age: 多大 and 几岁",id:"Menanyakan umur: 多大 dan 几岁"},explanation:{en:"你多大? (How old are you?) is the general, polite-enough question for adults and teens. 你几岁? uses 几 (expects a small number) and is typically used for young children. Note there's no verb 'to be' needed — age is stated directly with a number + 岁 (suì, 'years old'): 我今年二十岁 (I'm twenty this year). For very young children, ages under 10 sometimes drop 岁 informally, but at HSK 1 it's safest to always include 岁.",id:"你多大? (Berapa umurmu?) adalah pertanyaan umum yang cukup sopan untuk orang dewasa dan remaja. 你几岁? memakai 几 (mengharapkan jumlah kecil) dan biasanya dipakai untuk anak kecil. Perhatikan tidak perlu kata kerja 'menjadi/adalah' — umur dinyatakan langsung dengan angka + 岁 (suì, 'tahun'): 我今年二十岁 (Tahun ini umur saya dua puluh). Untuk anak sangat kecil, umur di bawah 10 kadang menghilangkan 岁 secara informal, tapi untuk level HSK 1 paling aman selalu menyertakan 岁."},examples:[{s:"你今年多大？",p:"nǐ jīn nián duō dà",en:"How old are you this year?",id:"Tahun ini umurmu berapa?"},{s:"我二十五岁。",p:"wǒ èr shí wǔ suì",en:"I'm twenty-five.",id:"Umur saya dua puluh lima tahun."},{s:"你女儿几岁了？",p:"nǐ nǚ ér jǐ suì le",en:"How old is your daughter?",id:"Anak perempuanmu umur berapa?"}],mistake:{wrong:"我是二十五岁。",right:"我二十五岁。",note:{en:"Age sentences don't use 是 — a number + 岁 directly follows the subject, no linking verb needed.",id:"Kalimat umur tidak memakai 是 — angka + 岁 langsung mengikuti subjek, tanpa kata kerja penghubung."}}},{id:"time-word-order",band:"1",fn:"time",pattern:"Time word + Subject/Verb (largest → smallest)",title:{en:"Dates, time & word order",id:"Tanggal, waktu, & urutan kata"},explanation:{en:"Chinese states time from largest unit to smallest: year → month → day → weekday → hour → minute, e.g. 2026年7月23号星期四早上八点 (8am, Thursday, July 23, 2026). Time expressions (both specific times and general ones like 今天, 现在) come BEFORE the verb, not after like in English: 我今天下午三点开会 (I have a meeting at 3pm today) — never ...开会今天下午三点. Weekday is 星期 + number (星期一 Monday ... 星期日/星期天 Sunday), month is number + 月, day of month is number + 号 (or formal 日).",id:"Bahasa Mandarin menyatakan waktu dari satuan terbesar ke terkecil: tahun → bulan → tanggal → hari → jam → menit, misalnya 2026年7月23号星期四早上八点 (jam 8 pagi, Kamis, 23 Juli 2026). Ungkapan waktu (baik waktu spesifik maupun umum seperti 今天, 现在) diletakkan SEBELUM kata kerja, bukan setelahnya seperti dalam bahasa Indonesia/Inggris: 我今天下午三点开会 (Saya ada rapat jam 3 sore ini) — jangan pernah ...开会今天下午三点. Hari dalam seminggu memakai 星期 + angka (星期一 Senin ... 星期日/星期天 Minggu), bulan memakai angka + 月, tanggal memakai angka + 号 (atau formal 日)."},examples:[{s:"我星期五有考试。",p:"wǒ xīng qī wǔ yǒu kǎo shì",en:"I have an exam on Friday.",id:"Saya ada ujian hari Jumat."},{s:"他八月十号过生日。",p:"tā bā yuè shí hào guò shēng rì",en:"His birthday is August 10th.",id:"Ulang tahunnya tanggal 10 Agustus."},{s:"我们现在去买东西。",p:"wǒ men xiàn zài qù mǎi dōng xi",en:"We're going shopping now.",id:"Kami sekarang pergi belanja."}],mistake:{wrong:"我去学校今天。",right:"我今天去学校。",note:{en:"Time words belong before the verb (right after the subject), not tacked on at the end of the sentence the way English often does.",id:"Kata keterangan waktu diletakkan sebelum kata kerja (tepat setelah subjek), bukan ditambahkan di akhir kalimat seperti kebiasaan dalam bahasa Indonesia/Inggris."}}},{id:"zai-vs-you",band:"2",fn:"time",pattern:"再 vs 又 + Verb",title:{en:"再 (zài) vs 又 (yòu) — repeating an action (not yet vs already)",id:"再 (zài) vs 又 (yòu) — mengulang tindakan (belum vs sudah terjadi)"},explanation:{en:"再 (zài) marks a repetition that hasn't happened yet — a planned, requested, or hypothetical 'again', so it pairs naturally with future markers like 会/要 and with commands: 明天再来 (come again tomorrow), 请再说一遍 (please say it one more time). 又 (yòu) marks a repetition that has already happened — you're reporting, as fact, that something recurred: 他又迟到了 (he was late again [it already happened]). The deciding question: has the repeat already taken place, or is it still ahead of you? Already happened → 又; still to come (a request, plan, or condition) → 再. Because 又 reports a completed recurrence, it never appears with 会/要, and 再 is the one that pairs with those future markers instead.",id:"再 (zài) menandai pengulangan yang BELUM terjadi — sesuatu yang direncanakan, diminta, atau bersifat andaikata, jadi wajar dipasangkan dengan penanda masa depan seperti 会/要 dan dengan kalimat perintah: 明天再来 (datang lagi besok), 请再说一遍 (tolong ulangi sekali lagi). 又 (yòu) menandai pengulangan yang SUDAH terjadi — kamu melaporkan sebagai fakta bahwa sesuatu terulang: 他又迟到了 (dia terlambat lagi [sudah terjadi]). Pertanyaan penentu: apakah pengulangan itu sudah terjadi, atau masih akan terjadi? Sudah terjadi → 又; masih akan terjadi (permintaan, rencana, atau syarat) → 再. Karena 又 melaporkan pengulangan yang sudah tuntas, 又 tidak pernah muncul bersama 会/要 — 再 lah yang berpasangan dengan penanda masa depan tersebut."},examples:[{s:"请再说一遍。",p:"qǐng zài shuō yí biàn",en:"Please say it one more time.",id:"Tolong katakan sekali lagi."},{s:"他昨天又迟到了。",p:"tā zuó tiān yòu chí dào le",en:"He was late again yesterday.",id:"Dia terlambat lagi kemarin."},{s:"他又迟到了，老师让他以后别再迟到。",p:"tā yòu chí dào le, lǎo shī ràng tā yǐ hòu bié zài chí dào",en:"He was late again; the teacher told him not to be late again in the future.",id:"Dia terlambat lagi, gurunya menyuruhnya jangan terlambat lagi di masa depan."}],mistake:{wrong:"我明天又去。",right:"我明天再去。",note:{en:"Talking about tomorrow (the future) requires 再, not 又 — 又 is reserved for repeats that have already happened.",id:"Membicarakan besok (masa depan) membutuhkan 再, bukan 又 — 又 khusus untuk pengulangan yang sudah terjadi."}}},{id:"haishi-vs-huozhe",band:"2",fn:"comparing",pattern:"A + 还是 + B？(questions) vs A + 或者 + B (statements)",title:{en:"还是 (háishi) vs 或者 (huòzhě) — 'or' in questions vs statements",id:"还是 (háishi) vs 或者 (huòzhě) — 'atau' dalam pertanyaan vs pernyataan"},explanation:{en:"还是 (háishi) and 或者 (huòzhě) both translate as 'or', but they belong to different sentence types. 还是 is for QUESTIONS where you're asking someone to choose between alternatives: 你喝茶还是咖啡？(Tea or coffee?) — the listener must pick one. 或者 is for STATEMENTS where either option is acceptable, no choice is being requested: 你可以喝茶，或者喝咖啡。(You can drink tea, or coffee — either is fine.) The deciding question: am I asking the listener to choose (→还是), or just stating that either option works (→或者)? A useful check: if the sentence could be answered with 'either one', it should be 或者; if the natural answer is picking A or B, it should be 还是.",id:"还是 (háishi) dan 或者 (huòzhě) sama-sama diterjemahkan 'atau', tapi keduanya dipakai pada jenis kalimat yang berbeda. 还是 dipakai dalam PERTANYAAN ketika kamu meminta lawan bicara memilih di antara pilihan yang ada: 你喝茶还是咖啡？(Mau teh atau kopi?) — lawan bicara harus memilih salah satu. 或者 dipakai dalam PERNYATAAN ketika kedua pilihan sama-sama boleh, tidak ada pilihan yang diminta: 你可以喝茶，或者喝咖啡。(Kamu boleh minum teh, atau kopi — dua-duanya boleh.) Pertanyaan penentu: apakah saya sedang meminta lawan bicara memilih (→还是), atau hanya menyatakan bahwa kedua pilihan sama-sama oke (→或者)? Cara mudah mengeceknya: kalau kalimat itu bisa dijawab dengan 'yang mana saja boleh', pakai 或者; kalau jawaban wajarnya memilih A atau B, pakai 还是."},examples:[{s:"你想喝茶还是咖啡？",p:"nǐ xiǎng hē chá hái shi kā fēi",en:"Do you want tea or coffee?",id:"Kamu mau minum teh atau kopi?"},{s:"周末我们可以看电影，或者在家休息。",p:"zhōu mò wǒ men kě yǐ kàn diàn yǐng, huò zhě zài jiā xiū xi",en:"On the weekend we can watch a movie, or rest at home.",id:"Akhir pekan kita bisa nonton film, atau istirahat di rumah."},{s:"你可以写信或者打电话，但你到底要写信还是打电话？",p:"nǐ kě yǐ xiě xìn huò zhě dǎ diàn huà, dàn nǐ dào dǐ yào xiě xìn hái shi dǎ diàn huà",en:"You can write a letter or make a call, but which will you actually do — write or call?",id:"Kamu bisa menulis surat atau menelepon, tapi sebenarnya kamu mau menulis surat atau menelepon?"}],mistake:{wrong:"你喝茶或者咖啡？",right:"你喝茶还是咖啡？",note:{en:"A question that asks the listener to choose between alternatives needs 还是, not 或者 — 或者 belongs in statements where either option is fine.",id:"Pertanyaan yang meminta lawan bicara memilih di antara pilihan membutuhkan 还是, bukan 或者 — 或者 dipakai dalam pernyataan di mana kedua pilihan sama-sama boleh."}}},{id:"er-vs-liang",band:"2",fn:"comparing",pattern:"两 + Measure word vs 二 (naming/counting the number)",title:{en:"二 (èr) vs 两 (liǎng) — counting a number vs quantifying things",id:"二 (èr) vs 两 (liǎng) — menyebut angka vs menghitung jumlah benda"},explanation:{en:"两 (liǎng) and 二 (èr) both mean 'two', but they aren't interchangeable. Use 两 right before a measure word when you're counting a quantity of things: 两个人 (two people), 两本书 (two books), 两天 (two days). Use 二 when you're naming or reciting the number itself — sequential counting (一, 二, 三...), phone numbers, page numbers, floor numbers, math, and inside compound numbers like 二十 (20) or 二百 (200). The deciding question: am I counting 'how many things' (→两 + measure word), or just stating/reading the number or label 'two' (→二)? One exception worth memorizing: even though floor/room numbers look like quantities, they're really labels, so they take 二 (二楼, not 两楼).",id:"两 (liǎng) dan 二 (èr) sama-sama berarti 'dua', tapi keduanya tidak bisa dipakai secara bergantian. Gunakan 两 tepat sebelum kata penggolong saat menghitung jumlah benda: 两个人 (dua orang), 两本书 (dua buku), 两天 (dua hari). Gunakan 二 saat menyebutkan atau membacakan angkanya sendiri — menghitung berurutan (一, 二, 三...), nomor telepon, nomor halaman, nomor lantai, hitungan matematika, dan di dalam angka gabungan seperti 二十 (dua puluh) atau 二百 (dua ratus). Pertanyaan penentu: apakah saya menghitung 'berapa banyak benda' (→两 + kata penggolong), atau hanya menyebut/membaca angka atau label 'dua' itu sendiri (→二)? Satu pengecualian yang perlu diingat: meskipun nomor lantai/kamar terlihat seperti jumlah, sebenarnya itu adalah label, jadi memakai 二 (二楼, bukan 两楼)."},examples:[{s:"我有两个妹妹。",p:"wǒ yǒu liǎng ge mèi mei",en:"I have two younger sisters.",id:"Saya punya dua adik perempuan."},{s:"他住在二楼。",p:"tā zhù zài èr lóu",en:"He lives on the second floor.",id:"Dia tinggal di lantai dua."},{s:"我买了两本书，一本二十块，一本二十二块。",p:"wǒ mǎi le liǎng běn shū, yì běn èr shí kuài, yì běn èr shí èr kuài",en:"I bought two books, one for 20 yuan, one for 22 yuan.",id:"Saya membeli dua buku, yang satu dua puluh yuan, yang satu lagi dua puluh dua yuan."}],mistake:{wrong:"我住在两楼。",right:"我住在二楼。",note:{en:"Floor numbers name the ordinal number itself (like a label), so use 二, not 两 — 二楼 (2nd floor), not 两楼. 两 only appears directly before a measure word counting a quantity of things.",id:"Nomor lantai menyebut angka itu sendiri (seperti label), jadi gunakan 二, bukan 两 — 二楼 (lantai 2), bukan 两楼. 两 hanya muncul tepat sebelum kata penggolong yang menghitung jumlah benda."}}},{id:"de-particles-triple",band:"2",fn:"comparing",pattern:"的 + Noun / 地 + Verb / Verb + 得 + Complement",title:{en:"的 (de) vs 得 (de) vs 地 (de) — three grammatical particles, one sound",id:"的 (de) vs 得 (de) vs 地 (de) — tiga partikel tata bahasa, satu bunyi"},explanation:{en:"的, 得, and 地 are all pronounced 'de' in neutral tone, but each has a different grammatical job. 的 attaches right before a NOUN, marking possession or description: 我的书 (my book), 漂亮的衣服 (pretty clothes). 地 attaches right before a VERB, turning a descriptive word into an adverb that describes how the action is done: 慢慢地走 (walk slowly). 得 attaches right AFTER a verb or adjective, introducing a complement that describes the result, degree, or manner of the action: 他跑得很快 (he runs very fast). The deciding question: what comes right after this 'de', and where does it sit relative to the verb? Before a noun → 的; before a verb, describing how the action happens → 地; after a verb/adjective, describing how well it turns out → 得.",id:"的, 得, dan 地 semuanya dilafalkan 'de' dengan nada netral, tapi masing-masing punya fungsi tata bahasa yang berbeda. 的 diletakkan tepat sebelum KATA BENDA, menandai kepemilikan atau deskripsi: 我的书 (buku saya), 漂亮的衣服 (baju yang cantik). 地 diletakkan tepat sebelum KATA KERJA, mengubah kata deskriptif menjadi kata keterangan yang menjelaskan bagaimana tindakan itu dilakukan: 慢慢地走 (berjalan pelan-pelan). 得 diletakkan tepat SETELAH kata kerja atau kata sifat, memperkenalkan pelengkap yang menjelaskan hasil, tingkat, atau cara tindakan itu dilakukan: 他跑得很快 (dia berlari sangat cepat). Pertanyaan penentu: apa yang muncul tepat setelah 'de' ini, dan di mana posisinya relatif terhadap kata kerja? Sebelum kata benda → 的; sebelum kata kerja, menjelaskan cara → 地; setelah kata kerja/sifat, menjelaskan seberapa baik hasilnya → 得."},examples:[{s:"这是我妈妈做的菜。",p:"zhè shì wǒ mā ma zuò de cài",en:"This is the dish my mom made.",id:"Ini masakan yang dibuat ibu saya."},{s:"你要慢慢地说，我才能听懂。",p:"nǐ yào màn màn de shuō, wǒ cái néng tīng dǒng",en:"You need to speak slowly so that I can understand.",id:"Kamu harus bicara pelan-pelan supaya saya bisa mengerti."},{s:"他汉语说得很流利。",p:"tā hàn yǔ shuō de hěn liú lì",en:"He speaks Chinese very fluently.",id:"Dia berbicara bahasa Mandarin dengan sangat lancar."}],mistake:{wrong:"他跑的很快。",right:"他跑得很快。",note:{en:"A complement describing how well/to what extent an action is done comes after the verb with 得, not 的 — 的 only ever sits directly before a noun.",id:"Pelengkap yang menjelaskan seberapa baik/sejauh mana suatu tindakan dilakukan diletakkan setelah kata kerja dengan 得, bukan 的 — 的 hanya diletakkan tepat sebelum kata benda."}}},{id:"le-vs-guo",band:"2",fn:"past",pattern:"Verb + 了 (completed instance) vs Verb + 过 (past experience)",title:{en:"了 (le) vs 过 (guo) — a completed instance vs a past experience",id:"了 (le) vs 过 (guo) — kejadian yang selesai vs pengalaman di masa lalu"},explanation:{en:"了 marks that an action is completed or happened, usually tied to a specific occasion you're reporting right now: 我吃了 (I ate / I've eaten [this time]). 过 marks that an action has been experienced at least once at some point in your life — the focus is on prior EXPERIENCE, not one specific occasion: 我吃过北京烤鸭 (I've had Peking duck before, at some point). The deciding question: am I reporting a specific completed instance (→了), or asserting that this is among my life experiences, a general 'ever' (→过)? Because of this, 'have never done X' always uses 没 + verb + 过, never 没 + verb + 了 — 了 disappears entirely in the negative, while 过 stays.",id:"了 menandai bahwa suatu tindakan sudah selesai atau terjadi, biasanya terkait dengan kejadian tertentu yang sedang kamu laporkan saat ini: 我吃了 (Saya sudah makan [kali ini]). 过 menandai bahwa suatu tindakan pernah dialami setidaknya sekali dalam hidupmu — fokusnya pada PENGALAMAN sebelumnya, bukan kejadian tertentu: 我吃过北京烤鸭 (Saya pernah makan bebek panggang Beijing, entah kapan). Pertanyaan penentu: apakah saya melaporkan satu kejadian tertentu yang sudah selesai (→了), atau menyatakan bahwa ini termasuk pengalaman hidup saya, 'pernah' secara umum (→过)? Karena itu, 'belum pernah melakukan X' selalu memakai 没 + kata kerja + 过, tidak pernah 没 + kata kerja + 了 — 了 hilang sepenuhnya dalam kalimat negatif, sedangkan 过 tetap ada."},examples:[{s:"我吃了晚饭。",p:"wǒ chī le wǎn fàn",en:"I ate dinner.",id:"Saya sudah makan malam."},{s:"我去过北京。",p:"wǒ qù guo běi jīng",en:"I've been to Beijing before.",id:"Saya pernah pergi ke Beijing."},{s:"我今天早上吃了药，以前也吃过这种药。",p:"wǒ jīn tiān zǎo shang chī le yào, yǐ qián yě chī guo zhè zhǒng yào",en:"I took medicine this morning, and I've taken this kind of medicine before too.",id:"Saya minum obat tadi pagi, dan saya juga pernah minum obat jenis ini sebelumnya."}],mistake:{wrong:"我从来没吃了臭豆腐。",right:"我从来没吃过臭豆腐。",note:{en:"'Have never done X' needs the experience marker 过 after the verb — 了 disappears entirely in negative sentences with 没, it never combines with 没 the way 过 does.",id:"'Belum pernah melakukan X' membutuhkan penanda pengalaman 过 setelah kata kerja — 了 dihilangkan sepenuhnya dalam kalimat negatif dengan 没, tidak seperti 过 yang justru berpasangan dengan 没."}}},{id:"zhengzai-vs-zhe",band:"2",fn:"time",pattern:"正在 + Verb (in progress) vs Verb + 着 (persisting state)",title:{en:"正在 (zhèngzài) vs 着 (zhe) — action happening now vs a state that persists",id:"正在 (zhèngzài) vs 着 (zhe) — tindakan yang sedang berlangsung vs keadaan yang bertahan"},explanation:{en:"正在 (zhèngzài, or just 在) sits BEFORE the verb to say an action is actively unfolding right now: 我正在吃饭 (I am [in the middle of] eating). 着 attaches AFTER a verb to show a state or posture that persists — often the backdrop for something else happening: 门开着 (the door is [in the state of being] open), 他坐着看书 (he's seated, reading — 着 marks that the sitting posture holds while the reading happens). The deciding question: is the sentence about an action unfolding dynamically right now (→正在 before the verb), or a state/posture being maintained, often as the background for another action (→verb + 着)? The two often combine: 他正在躺着看电视 (he's currently lying down watching TV) — 正在 says it's happening now, 着 says 'lying down' is the persisting posture.",id:"正在 (zhèngzài, atau cukup 在) diletakkan SEBELUM kata kerja untuk menyatakan bahwa suatu tindakan sedang berlangsung aktif saat ini: 我正在吃饭 (Saya sedang makan). 着 diletakkan SETELAH kata kerja untuk menunjukkan keadaan atau posisi yang bertahan — sering menjadi latar belakang bagi hal lain yang sedang terjadi: 门开着 (pintunya dalam keadaan terbuka), 他坐着看书 (dia duduk sambil membaca — 着 menandai bahwa posisi duduknya bertahan selama kegiatan membaca berlangsung). Pertanyaan penentu: apakah kalimat ini membicarakan tindakan yang sedang berlangsung secara dinamis saat ini (→正在 sebelum kata kerja), atau keadaan/posisi yang dipertahankan, sering sebagai latar bagi tindakan lain (→kata kerja + 着)? Keduanya sering digabung: 他正在躺着看电视 (dia sedang berbaring menonton TV) — 正在 menyatakan itu terjadi sekarang, 着 menyatakan 'berbaring' adalah posisi yang bertahan."},examples:[{s:"我正在写作业。",p:"wǒ zhèng zài xiě zuò yè",en:"I am (in the middle of) doing my homework.",id:"Saya sedang mengerjakan PR."},{s:"墙上挂着一张地图。",p:"qiáng shàng guà zhe yì zhāng dì tú",en:"A map is hanging on the wall.",id:"Ada peta yang tergantung di dinding."},{s:"他正在门口站着等你。",p:"tā zhèng zài mén kǒu zhàn zhe děng nǐ",en:"He is currently standing at the doorway waiting for you.",id:"Dia sedang berdiri di depan pintu menunggumu."}],mistake:{wrong:"墙上正在挂一张画。",right:"墙上挂着一张画。",note:{en:"A static, unchanging state (a picture hanging on the wall) uses 着, not 正在 — 正在 signals a dynamic action unfolding right now, but hanging-in-place is a passive resulting state, not an ongoing activity.",id:"Keadaan statis yang tidak berubah (lukisan yang tergantung di dinding) memakai 着, bukan 正在 — 正在 menandakan tindakan dinamis yang sedang berlangsung, sedangkan 'tergantung' adalah keadaan hasil yang pasif, bukan aktivitas yang sedang terjadi."}}},{id:"jiu-vs-cai",band:"2",fn:"time",pattern:"Time/condition + 就 (sooner than expected) vs 才 (later than expected) + Verb",title:{en:"就 (jiù) vs 才 (cái) — sooner/easier than expected vs later/harder than expected",id:"就 (jiù) vs 才 (cái) — lebih cepat/mudah dari dugaan vs lebih lambat/sulit dari dugaan"},explanation:{en:"就 (jiù) and 才 (cái) both often follow a time or condition before the verb, but they signal opposite feelings about timing versus expectation. 就 signals something happens sooner, more easily, or more readily than expected — 'already, as early as, right away': 他六点就到了 (he'd already arrived by six — that's early!). 才 signals something happens later, with more effort, or only once a condition is met — 'not until, only then': 他八点才到 (he didn't arrive until eight — that's late!). The deciding question: does the timing feel surprisingly EARLY or effortless (→就), or surprisingly LATE or effortful (→才)? 就 can also mean a quick, natural consequence ('then, so'): 你一说，我就明白了 (as soon as you said it, I got it right away); 才 can mean 'only then, only if': 你解释了，我才明白 (only after you explained did I understand).",id:"就 (jiù) dan 才 (cái) sering sama-sama mengikuti keterangan waktu atau syarat sebelum kata kerja, tapi keduanya menyiratkan kesan yang berlawanan soal waktu dibanding harapan. 就 menyiratkan sesuatu terjadi lebih cepat, lebih mudah, atau lebih siap dari dugaan — 'sudah, sedini, langsung': 他六点就到了 (dia sudah tiba jam enam — pagi sekali!). 才 menyiratkan sesuatu terjadi lebih lambat, lebih susah, atau baru terjadi setelah suatu syarat terpenuhi — 'baru, barulah': 他八点才到 (dia baru tiba jam delapan — telat!). Pertanyaan penentu: apakah waktunya terasa lebih CEPAT atau lebih mudah dari dugaan (→就), atau terasa lebih LAMBAT atau lebih sulit dari dugaan (→才)? 就 juga bisa berarti akibat yang cepat dan wajar ('jadi, maka'): 你一说，我就明白了 (begitu kamu bilang, saya langsung mengerti); 才 bisa berarti 'baru, hanya jika': 你解释了，我才明白 (setelah kamu jelaskan, barulah saya mengerti)."},examples:[{s:"他六点就起床了，真早！",p:"tā liù diǎn jiù qǐ chuáng le, zhēn zǎo",en:"He was already up by six — so early!",id:"Dia sudah bangun jam enam, pagi sekali!"},{s:"我等了半天，他十点才来。",p:"wǒ děng le bàn tiān, tā shí diǎn cái lái",en:"I waited forever; he didn't come until ten.",id:"Saya menunggu lama sekali, dia baru datang jam sepuluh."},{s:"我八点就到了，可是老师九点才来。",p:"wǒ bā diǎn jiù dào le, kě shì lǎo shī jiǔ diǎn cái lái",en:"I had already arrived by eight, but the teacher didn't come until nine.",id:"Saya sudah tiba jam delapan, tapi gurunya baru datang jam sembilan."}],mistake:{wrong:"他每天很早就起床，可是我很晚就起床。",right:"他每天很早就起床，可是我很晚才起床。",note:{en:"Getting up LATE is the slow/unexpected outcome, so it needs 才, not 就 — 就 would suggest getting up late was surprisingly quick or easy, which contradicts 很晚 (very late).",id:"Bangun TERLAMBAT adalah hal yang lambat/tidak terduga, jadi butuh 才, bukan 就 — 就 justru menyiratkan bangun terlambat itu terjadi dengan cepat atau mudah, yang bertentangan dengan 很晚 (sangat larut)."}}},{id:"gang-vs-gangcai",band:"2",fn:"time",pattern:"刚 + Verb (right before the verb) vs 刚才 (standalone time word)",title:{en:"刚 (gāng) vs 刚才 (gāngcái) — 'just did' vs 'a moment ago'",id:"刚 (gāng) vs 刚才 (gāngcái) — 'baru saja melakukan' vs 'barusan/tadi'"},explanation:{en:"刚 (gāng) is an adverb that sits directly in front of a verb, saying the action happened only moments ago: 我刚到 (I just arrived). 刚才 (gāngcái) is a time word meaning 'a moment ago, just now' — it behaves like other time expressions, so it can open the sentence, come before the subject, or even stand alone as an answer: 你什么时候到的？——刚才。(When did you arrive? — Just now.) The deciding question: do I need a word glued right in front of the verb, with nothing else able to come before it (→刚), or a fuller time expression that can head the sentence or stand alone (→刚才)? Because 刚 must directly precede the verb, it can never open a sentence before the subject — that position belongs to 刚才.",id:"刚 (gāng) adalah kata keterangan yang diletakkan tepat di depan kata kerja, menyatakan bahwa tindakan itu baru saja terjadi: 我刚到 (Saya baru saja tiba). 刚才 (gāngcái) adalah kata keterangan waktu yang berarti 'barusan, tadi' — perilakunya seperti ungkapan waktu lain, jadi bisa membuka kalimat, muncul sebelum subjek, bahkan berdiri sendiri sebagai jawaban: 你什么时候到的？——刚才。(Kapan kamu tiba? — Barusan.) Pertanyaan penentu: apakah saya butuh kata yang menempel tepat di depan kata kerja, tanpa apa pun di depannya (→刚), atau ungkapan waktu yang lebih lengkap yang bisa membuka kalimat atau berdiri sendiri (→刚才)? Karena 刚 harus langsung berada di depan kata kerja, 刚 tidak pernah bisa membuka kalimat sebelum subjek — posisi itu milik 刚才."},examples:[{s:"我刚到家。",p:"wǒ gāng dào jiā",en:"I just got home.",id:"Saya baru saja sampai di rumah."},{s:"刚才谁给我打电话了？",p:"gāng cái shéi gěi wǒ dǎ diàn huà le",en:"Who called me just now?",id:"Siapa yang menelepon saya barusan?"},{s:"刚才他还在这儿，怎么刚一转身就不见了？",p:"gāng cái tā hái zài zhèr, zěn me gāng yì zhuǎn shēn jiù bú jiàn le",en:"He was right here a moment ago — how did he vanish the instant I turned around?",id:"Barusan dia masih ada di sini, kenapa begitu saya berbalik badan dia langsung menghilang?"}],mistake:{wrong:"刚我去了洗手间。",right:"刚才我去了洗手间。",note:{en:"刚 must sit directly in front of the verb (我刚去), never before the subject at the start of a sentence — for that opening position, use the standalone time word 刚才.",id:"刚 harus diletakkan tepat sebelum kata kerja (我刚去), tidak pernah sebelum subjek di awal kalimat — untuk posisi awal kalimat itu, gunakan kata keterangan waktu yang berdiri sendiri, yaitu 刚才."}}},{id:"juede-vs-renwei",band:"2",fn:"comparing",pattern:"我觉得 + Clause (feeling) vs 我认为 + Clause (reasoned opinion)",title:{en:"觉得 (juéde) vs 认为 (rènwéi) — feeling/impression vs reasoned opinion",id:"觉得 (juéde) vs 认为 (rènwéi) — perasaan/kesan vs pendapat yang beralasan"},explanation:{en:"觉得 (juéde) and 认为 (rènwéi) both roughly mean 'to think/feel that' and are both followed directly by a clause, but they differ in tone. 觉得 expresses a personal feeling, impression, or tentative opinion — softer and more casual, and it's also the only one of the two used for physical sensations: 我觉得这个电影很好看 (I think this movie is good), 我觉得冷 (I feel cold). 认为 expresses a more considered, reasoned belief or firm judgment — more formal, common in analysis, debate, or stating expert views: 专家认为这个方法有效 (experts hold that this method is effective). The deciding question: am I sharing a casual feeling/impression, or something about my body (→觉得), or asserting a reasoned, more objective stance (→认为)? 认为 never describes physical sensations.",id:"觉得 (juéde) dan 认为 (rènwéi) sama-sama kurang lebih berarti 'merasa/berpendapat bahwa' dan sama-sama langsung diikuti klausa, tapi nadanya berbeda. 觉得 mengungkapkan perasaan pribadi, kesan, atau pendapat yang belum pasti — lebih lembut dan santai, dan juga satu-satunya yang dipakai untuk sensasi fisik: 我觉得这个电影很好看 (Saya rasa film ini bagus), 我觉得冷 (Saya merasa dingin). 认为 mengungkapkan keyakinan yang lebih dipikirkan matang atau penilaian yang tegas — lebih formal, umum dipakai dalam analisis, debat, atau menyatakan pandangan ahli: 专家认为这个方法有效 (para ahli berpendapat metode ini efektif). Pertanyaan penentu: apakah saya sedang membagikan perasaan/kesan santai, atau sesuatu tentang tubuh saya (→觉得), atau menyatakan sikap yang lebih beralasan dan objektif (→认为)? 认为 tidak pernah dipakai untuk sensasi fisik."},examples:[{s:"我觉得这个菜很好吃。",p:"wǒ jué de zhè ge cài hěn hǎo chī",en:"I think this dish is delicious.",id:"Saya rasa masakan ini enak sekali."},{s:"专家认为空气污染很严重。",p:"zhuān jiā rèn wéi kōng qì wū rǎn hěn yán zhòng",en:"Experts believe air pollution is very serious.",id:"Para ahli berpendapat polusi udara sangat serius."},{s:"我觉得有点儿累，但医生认为我身体很健康。",p:"wǒ jué de yǒu diǎnr lèi, dàn yī shēng rèn wéi wǒ shēn tǐ hěn jiàn kāng",en:"I feel a bit tired, but the doctor believes my body is very healthy.",id:"Saya merasa agak lelah, tapi dokter berpendapat tubuh saya sangat sehat."}],mistake:{wrong:"我认为有点儿冷。",right:"我觉得有点儿冷。",note:{en:"Physical sensations (cold, tired, hungry, sick) always use 觉得, never 认为 — 认为 is reserved for reasoned opinions and judgments, not bodily feelings.",id:"Sensasi fisik (dingin, lelah, lapar, sakit) selalu memakai 觉得, tidak pernah 认为 — 认为 khusus untuk pendapat dan penilaian yang beralasan, bukan perasaan tubuh."}}},{id:"ba-construction",band:"2",fn:"objects",pattern:"Subject + 把 + Object + Verb + Result/了/Complement",title:{en:"The 把 (bǎ) construction — spotlighting what happens to an object",id:"Konstruksi 把 (bǎ) — menyoroti apa yang terjadi pada suatu objek"},explanation:{en:"Normal Chinese word order is Subject-Verb-Object, but when you want to spotlight what HAPPENS TO a specific, already-known object — moving it, changing it, finishing it, disposing of it — Chinese often fronts the object with 把 right after the subject, then follows the verb with an extra element (了, a result complement, a directional complement, or a location phrase) showing the object's outcome. Compare plain 我吃了那个苹果 with the 把-sentence 我把那个苹果吃了 — same basic meaning, but 把 puts 'that apple' in the spotlight as a specific thing that got fully dealt with. The deciding question: is the object specific and definite (not 'a/some' thing), and do I want to highlight its fate — and does the verb have something after it describing the result? If either answer is no, skip 把. A bare verb can never end a 把-sentence: 我把苹果吃 is wrong; it needs 了 or a complement.",id:"Urutan kata normal dalam bahasa Mandarin adalah Subjek-Kata Kerja-Objek, tapi ketika kamu ingin menyoroti apa yang TERJADI PADA suatu objek tertentu yang sudah diketahui — memindahkannya, mengubahnya, menyelesaikannya, atau membuangnya — bahasa Mandarin sering memajukan objek itu dengan 把 tepat setelah subjek, lalu mengikuti kata kerja dengan unsur tambahan (了, pelengkap hasil, pelengkap arah, atau frasa lokasi) yang menunjukkan nasib objek tersebut. Bandingkan kalimat biasa 我吃了那个苹果 dengan kalimat 把 我把那个苹果吃了 — artinya dasarnya sama, tapi 把 menyoroti 'apel itu' sebagai benda tertentu yang benar-benar sudah dituntaskan. Pertanyaan penentu: apakah objeknya spesifik dan pasti (bukan 'sebuah/beberapa' benda), dan apakah saya ingin menonjolkan nasibnya — serta apakah kata kerjanya diikuti sesuatu yang menjelaskan hasilnya? Jika salah satu jawabannya tidak, jangan pakai 把. Kata kerja polos tidak bisa mengakhiri kalimat 把: 我把苹果吃 salah; harus ditambah 了 atau pelengkap."},examples:[{s:"我把作业做完了。",p:"wǒ bǎ zuò yè zuò wán le",en:"I finished (doing) my homework.",id:"Saya sudah menyelesaikan PR saya."},{s:"请把窗户打开。",p:"qǐng bǎ chuāng hu dǎ kāi",en:"Please open the window.",id:"Tolong buka jendelanya."},{s:"他把手机放在桌子上了。",p:"tā bǎ shǒu jī fàng zài zhuō zi shàng le",en:"He put his phone on the table.",id:"Dia meletakkan ponselnya di atas meja."}],mistake:{wrong:"我把苹果吃。",right:"我把苹果吃了。",note:{en:"A 把-sentence always needs something after the verb — 了, a result complement, a location phrase — showing what happened to the object. A bare verb can't end a 把-sentence.",id:"Kalimat 把 selalu membutuhkan sesuatu setelah kata kerja — 了, pelengkap hasil, atau frasa lokasi — yang menunjukkan apa yang terjadi pada objek tersebut. Kata kerja polos saja tidak bisa mengakhiri kalimat 把."}}},{id:"bei-construction",band:"2",fn:"objects",pattern:"Subject(affected) + 被 + (Agent) + Verb + Result/了/Complement",title:{en:"The 被 (bèi) construction — passive voice",id:"Konstruksi 被 (bèi) — kalimat pasif"},explanation:{en:"被 (bèi) marks the passive voice — the sentence's subject is the one something was DONE TO, not the doer. Structure: affected thing/person + 被 + (optionally, who did it) + verb + an extra element (了, a result complement): 我的钱包被(小偷)偷了 (my wallet was stolen [by a thief]). Like 把, a 被-sentence's verb almost always needs something after it — a bare verb alone feels incomplete. Chinese uses passive voice less often than English, and mainly when something negative or noteworthy happened to the object; many English passive sentences read more naturally in Chinese as plain active sentences or 把-sentences instead. The deciding question: do I need to emphasize that the subject was affected by an action — often something unwanted — rather than describe who did it? If you're just narrating a normal completed action from the doer's side, plain word order or 把 is usually more natural than forcing 被.",id:"被 (bèi) menandai kalimat pasif — subjek kalimatnya adalah pihak yang DIKENAI suatu tindakan, bukan pelakunya. Strukturnya: benda/orang yang terkena + 被 + (opsional, siapa pelakunya) + kata kerja + unsur tambahan (了, pelengkap hasil): 我的钱包被(小偷)偷了 (dompet saya dicuri [oleh pencuri]). Seperti kalimat 把, kata kerja dalam kalimat 被 hampir selalu membutuhkan sesuatu setelahnya — kata kerja polos saja terasa belum tuntas. Bahasa Mandarin memakai kalimat pasif lebih jarang dibanding bahasa Inggris, dan biasanya hanya ketika sesuatu yang negatif atau penting terjadi pada objeknya; banyak kalimat pasif bahasa Inggris justru lebih natural diterjemahkan sebagai kalimat aktif biasa atau kalimat 把 dalam bahasa Mandarin. Pertanyaan penentu: apakah saya perlu menekankan bahwa subjeknya terkena suatu tindakan — sering kali sesuatu yang tidak diinginkan — alih-alih menjelaskan siapa pelakunya? Kalau saya hanya menceritakan tindakan selesai yang biasa dari sudut pandang pelakunya, urutan kata biasa atau kalimat 把 biasanya lebih natural daripada memaksakan 被."},examples:[{s:"我的自行车被偷了。",p:"wǒ de zì xíng chē bèi tōu le",en:"My bike was stolen.",id:"Sepeda saya dicuri."},{s:"那本书被他借走了。",p:"nà běn shū bèi tā jiè zǒu le",en:"That book was borrowed by him.",id:"Buku itu dipinjam olehnya."},{s:"杯子被小猫打破了。",p:"bēi zi bèi xiǎo māo dǎ pò le",en:"The cup was broken by the kitten.",id:"Gelasnya dipecahkan oleh anak kucing itu."}],mistake:{wrong:"杯子被打破。",right:"杯子被打破了。",note:{en:"Like 把, a 被-sentence needs a completing element after the verb (了, a result complement) — a bare verb leaves the sentence feeling unfinished.",id:"Seperti kalimat 把, kalimat 被 membutuhkan unsur pelengkap setelah kata kerja (了, pelengkap hasil) — kata kerja polos saja membuat kalimatnya terasa belum selesai."}}},{id:"directional-complement-lai-qu",band:"2",fn:"describing",pattern:"Verb + 来 (toward speaker) vs Verb + 去 (away from speaker)",title:{en:"Directional complements 来 vs 去 — toward vs away from the speaker",id:"Pelengkap arah 来 vs 去 — menuju vs menjauhi pembicara"},explanation:{en:"After many action verbs, 来 (lái) or 去 (qù) shows the direction of movement RELATIVE TO THE SPEAKER (or the story's point of view): 来 = toward here/the speaker, 去 = away from here, toward somewhere else. That's why the same verb splits into pairs: 进来 (come in, toward me) vs 进去 (go in, away from me); 回来 (come back, toward here) vs 回去 (go back, to another place); 上来/上去 (come up/go up), 下来/下去 (come down/go down), 出来/出去 (come out/go out). The deciding question: from the speaker's (or the story's) position, is the movement heading TOWARD here (→来), or AWAY from here (→去)? A classic beginner slip is picking 去 while describing someone approaching where you are, or vice versa — always check where the speaker is standing before choosing.",id:"Setelah banyak kata kerja tindakan, 来 (lái) atau 去 (qù) menunjukkan arah gerakan RELATIF TERHADAP PEMBICARA (atau sudut pandang ceritanya): 来 = menuju ke sini/ke arah pembicara, 去 = menjauh dari sini, menuju ke tempat lain. Itu sebabnya kata kerja yang sama terbagi menjadi pasangan: 进来 (masuk, menuju saya) vs 进去 (masuk, menjauhi saya); 回来 (kembali, menuju ke sini) vs 回去 (kembali, ke tempat lain); 上来/上去 (naik ke sini/naik ke sana), 下来/下去 (turun ke sini/turun ke sana), 出来/出去 (keluar ke sini/keluar ke sana). Pertanyaan penentu: dari posisi pembicara (atau sudut pandang cerita), apakah gerakan itu menuju KE SINI (→来), atau MENJAUH dari sini (→去)? Kesalahan klasik pemula adalah memilih 去 saat menggambarkan seseorang yang mendekat ke tempat pembicara berada, atau sebaliknya — selalu cek dulu di mana posisi pembicara sebelum memilih."},examples:[{s:"快进来，外面很冷。",p:"kuài jìn lái, wài miàn hěn lěng",en:"Come in quickly, it's cold outside.",id:"Cepat masuk, di luar dingin sekali."},{s:"他明天回去看父母。",p:"tā míng tiān huí qù kàn fù mǔ",en:"He's going back tomorrow to see his parents.",id:"Besok dia pulang untuk menjenguk orang tuanya."},{s:"你先上去，我马上就上来。",p:"nǐ xiān shàng qù, wǒ mǎ shàng jiù shàng lái",en:"You go up first, I'll come up right away.",id:"Kamu naik duluan, saya akan segera menyusul naik."}],mistake:{wrong:"你快进去吧！",right:"你快进来吧！",note:{en:"Said by someone already standing inside, calling to a person outside: since the speaker is inside, someone entering is moving TOWARD the speaker, so 来 (进来) is correct — 去 (进去) would mean moving away from the speaker into somewhere else.",id:"Diucapkan oleh seseorang yang sudah berada di dalam, memanggil orang di luar: karena pembicara sudah di dalam, orang yang masuk itu bergerak MENUJU pembicara, jadi 来 (进来) yang benar — 去 (进去) berarti bergerak menjauhi pembicara ke tempat lain."}}},{id:"result-complements",band:"2",fn:"describing",pattern:"Verb + 完 / 到 / 见 / 好 — result complements",title:{en:"Result complements 完/到/见/好 — how the action turned out",id:"Pelengkap hasil 完/到/见/好 — bagaimana tindakan itu berakhir"},explanation:{en:"Placed directly after a verb, a result complement says what became of the action — not just that it happened, but how it turned out. 完 (wán) = finished, nothing left: 吃完 (finish eating), 做完 (finish doing/making). 到 (dào) = successfully reached, achieved, or made contact with a goal: 找到 (found it — the search succeeded), 买到 (managed to buy it). 见 (jiàn) = registered through the senses, mainly sight and sound: 看见 (caught sight of), 听见 (caught the sound of). 好 (hǎo) = done properly, satisfactorily, ready: 准备好了 (all prepared), 收拾好了 (packed up properly). The deciding question: what exactly resulted from the action — nothing left (→完), a goal achieved (→到), something perceived by the senses (→见), or a task properly finished and ready (→好)? These complements attach directly to the bare verb and are negated with 没 (没吃完 — didn't finish eating), not with plain 不.",id:"Diletakkan tepat setelah kata kerja, pelengkap hasil menyatakan apa yang terjadi pada tindakan itu — bukan sekadar bahwa tindakan itu terjadi, tapi bagaimana hasilnya. 完 (wán) = selesai, tidak ada sisa: 吃完 (selesai makan), 做完 (selesai mengerjakan/membuat). 到 (dào) = berhasil mencapai, meraih, atau menyentuh suatu target: 找到 (berhasil menemukan — pencariannya berhasil), 买到 (berhasil membeli). 见 (jiàn) = terekam oleh indra, terutama penglihatan dan pendengaran: 看见 (terlihat, tertangkap mata), 听见 (terdengar, tertangkap telinga). 好 (hǎo) = selesai dengan baik, memuaskan, siap: 准备好了 (sudah siap sepenuhnya), 收拾好了 (sudah dibereskan dengan rapi). Pertanyaan penentu: apa tepatnya hasil dari tindakan itu — tidak ada sisa (→完), target tercapai (→到), sesuatu yang tertangkap indra (→见), atau tugas selesai dengan baik dan siap (→好)? Pelengkap-pelengkap ini menempel langsung pada kata kerja polos dan dinegasikan dengan 没 (没吃完 — belum selesai makan), bukan dengan 不 biasa."},examples:[{s:"行李我已经收拾好了。",p:"xíng li wǒ yǐ jīng shōu shi hǎo le",en:"I've already packed the luggage properly.",id:"Koper sudah saya beres-beres dengan rapi."},{s:"我终于找到我的钥匙了，可是作业还没做完。",p:"wǒ zhōng yú zhǎo dào wǒ de yào shi le, kě shì zuò yè hái méi zuò wán",en:"I finally found my keys, but I still haven't finished my homework.",id:"Saya akhirnya menemukan kunci saya, tapi PR saya belum selesai."},{s:"我看见他了，可是没听见他说什么。",p:"wǒ kàn jiàn tā le, kě shì méi tīng jiàn tā shuō shén me",en:"I saw him, but I didn't hear what he said.",id:"Saya melihatnya, tapi tidak mendengar apa yang dia katakan."}],mistake:{wrong:"我做到作业了。",right:"我做完作业了。",note:{en:"Finishing an assignment (using up all the work, nothing left) needs 完 — 到 marks successfully reaching or achieving a target (找到 — found it, 做到 — accomplished/achieved a goal), which is a different result from simply finishing a task.",id:"Menyelesaikan PR (mengerjakan semuanya sampai habis) memakai 完 — 到 menandai berhasil mencapai atau meraih sebuah target (找到 — berhasil menemukan, 做到 — berhasil mencapai/mewujudkan), hasil yang berbeda dari sekadar menyelesaikan tugas."}}},{id:"ba-advanced",band:"3",fn:"objects",pattern:"别/没/不 + 把 + Object + Verb + 成/给/在 + Complement",title:{en:"The 把 (bǎ) construction, advanced — negation placement and 成/给/在 complements",id:"Konstruksi 把 (bǎ) tingkat lanjut — posisi negasi dan pelengkap 成/给/在"},explanation:{en:"Building on the basic 把-sentence, two things trip learners up at HSK 3. First, negation and modal verbs (不, 没, 别, 想, 要, 应该) always sit BEFORE 把, never between 把 and the verb — 我把作业没做完 is wrong; it must be 我没把作业做完. Second, the complement after the verb can specify exactly what happened: 成 (chéng) shows the object was turned INTO something else — 他把美元换成人民币了 (he changed the dollars into RMB); 给 (gěi) shows the object was handed over TO someone — 我把书还给你了 (I gave the book back to you); 在 (zài) shows the object ended up settled AT a location — 他把车停在门口了 (he parked the car at the door). The deciding question: do I need to negate or add a modal verb — put it before 把, never after? And which complement matches the outcome — became something (成), went to someone (给), or ended up somewhere (在)? A bare verb still can never end a 把-sentence, even here.",id:"Berdasarkan kalimat 把 dasar, ada dua hal yang sering bikin pelajar HSK 3 keliru. Pertama, negasi dan kata kerja modal (不, 没, 别, 想, 要, 应该) selalu diletakkan SEBELUM 把, tidak pernah di antara 把 dan kata kerja — 我把作业没做完 salah; yang benar 我没把作业做完. Kedua, pelengkap setelah kata kerja bisa menjelaskan persis apa yang terjadi: 成 (chéng) menunjukkan objek berubah MENJADI sesuatu yang lain — 他把美元换成人民币了 (dia menukar dolar menjadi renminbi); 给 (gěi) menunjukkan objek diserahkan KEPADA seseorang — 我把书还给你了 (saya sudah mengembalikan buku itu kepadamu); 在 (zài) menunjukkan objek berakhir menetap DI suatu tempat — 他把车停在门口了 (dia memarkir mobilnya di depan pintu). Pertanyaan penentu: apakah saya perlu menegasikan atau menambah kata kerja modal — letakkan sebelum 把, jangan sesudahnya? Dan pelengkap mana yang cocok dengan hasilnya — berubah jadi sesuatu (成), berpindah ke seseorang (给), atau berakhir di suatu tempat (在)? Kata kerja polos tetap tidak bisa mengakhiri kalimat 把, bahkan di sini."},examples:[{s:"我没把作业做完，明天再交。",p:"wǒ méi bǎ zuò yè zuò wán, míng tiān zài jiāo",en:"I didn't finish the homework, I'll hand it in tomorrow.",id:"Saya belum menyelesaikan PR, besok saya kumpulkan lagi."},{s:"他把美元换成人民币了。",p:"tā bǎ měi yuán huàn chéng rén mín bì le",en:"He changed the dollars into RMB.",id:"Dia menukar dolar menjadi renminbi."},{s:"请把这本书还给图书馆。",p:"qǐng bǎ zhè běn shū huán gěi tú shū guǎn",en:"Please return this book to the library.",id:"Tolong kembalikan buku ini ke perpustakaan."}],mistake:{wrong:"我把作业没做完。",right:"我没把作业做完。",note:{en:"Negation goes before 把, not between 把 and the verb — 把 always keeps the object and verb glued together as a unit.",id:"Negasi diletakkan sebelum 把, bukan di antara 把 dan kata kerja — 把 selalu menyatukan objek dan kata kerja sebagai satu kesatuan."}}},{id:"bei-rang-jiao",band:"3",fn:"objects",pattern:"Subject(affected) + 被/让/叫 + Agent + Verb + Complement",title:{en:"被 (bèi) vs 让 (ràng) vs 叫 (jiào) — three ways to mark the passive",id:"被 (bèi) vs 让 (ràng) vs 叫 (jiào) — tiga cara menandai kalimat pasif"},explanation:{en:"被, 让, and 叫 can all mark a passive sentence (X was done-to by Y), but they carry different shades. 被 is the neutral, most written/formal choice and is the only one of the three that can drop the agent entirely: 钱包被偷了 (the wallet was stolen [by someone unnamed]) is fine, but 钱包让偷了 or 钱包叫偷了 sound incomplete — 让 and 叫 almost always need an explicit agent stated. 让 and 叫 are more spoken/colloquial and, because they're also the verbs for 'let/allow' (让) and 'call/order' (叫) in other contexts, they carry a faint flavor of the affected party being 'made to' experience something by that agent: 我让老板骂了一顿 (I got scolded [lit. was 'let/made' to be scolded] by my boss). The deciding question: is the agent known and worth naming (→ any of the three work, with 让/叫 sounding more casual), or unknown/unimportant (→ 被 is the only natural choice, since it alone can omit the agent)? In formal writing, default to 被.",id:"被, 让, dan 叫 sama-sama bisa menandai kalimat pasif (X dikenai tindakan oleh Y), tapi nuansanya berbeda. 被 adalah pilihan yang netral dan paling formal/tertulis, dan satu-satunya di antara ketiganya yang bisa menghilangkan pelakunya sama sekali: 钱包被偷了 (dompetnya dicuri [oleh seseorang yang tidak disebutkan]) sudah benar, tapi 钱包让偷了 atau 钱包叫偷了 terasa belum lengkap — 让 dan 叫 hampir selalu membutuhkan pelaku yang disebutkan secara eksplisit. 让 dan 叫 lebih bersifat lisan/santai, dan karena keduanya juga berarti 'membiarkan/mengizinkan' (让) dan 'memanggil/menyuruh' (叫) dalam konteks lain, keduanya membawa sedikit nuansa bahwa pihak yang terkena itu 'dibuat' mengalami sesuatu oleh pelakunya: 我让老板骂了一顿 (saya kena marah [seolah 'dibuat' dimarahi] oleh bos saya). Pertanyaan penentu: apakah pelakunya diketahui dan layak disebut (→ ketiganya bisa dipakai, dengan 让/叫 terdengar lebih santai), atau tidak diketahui/tidak penting (→ 被 satu-satunya pilihan yang wajar, karena hanya 被 yang bisa menghilangkan pelaku)? Dalam tulisan formal, gunakan 被 sebagai pilihan default."},examples:[{s:"我的钱包被偷了。",p:"wǒ de qián bāo bèi tōu le",en:"My wallet was stolen.",id:"Dompet saya dicuri."},{s:"他让老板骂了一顿。",p:"tā ràng lǎo bǎn mà le yí dùn",en:"He got scolded by his boss.",id:"Dia dimarahi habis-habisan oleh bosnya."},{s:"杯子叫弟弟打破了，不过没人知道是谁做的。",p:"bēi zi jiào dì di dǎ pò le, bú guò méi rén zhī dào shì shéi zuò de",en:"The cup was broken by little brother, though no one knows it was him.",id:"Gelasnya dipecahkan oleh adik laki-laki, tapi tidak ada yang tahu itu ulahnya."}],mistake:{wrong:"钱包叫偷了。",right:"钱包被偷了。",note:{en:"叫 (like 让) almost always needs an explicit agent after it — to describe theft by an unnamed/unknown thief, use 被, the only one of the three that can drop the agent.",id:"叫 (seperti 让) hampir selalu membutuhkan pelaku yang disebutkan secara eksplisit setelahnya — untuk menggambarkan pencurian oleh pencuri yang tidak disebutkan/tidak diketahui, gunakan 被, satu-satunya di antara ketiganya yang bisa menghilangkan pelaku."}}},{id:"de-degree-complement",band:"3",fn:"describing",pattern:"Verb(+Object) + Verb + 得 + Degree Complement",title:{en:"得 (de) complements of degree — verb reduplication with objects, and negating inside the complement",id:"Pelengkap tingkat 得 — pengulangan kata kerja saat ada objek, dan negasi di dalam pelengkap"},explanation:{en:"A 得-complement (see also the 的/得/地 comparison point) describes how well, how much, or to what degree an action happens: 他跑得很快 (he runs very fast). Two extra rules matter once the verb takes an object. First, if there's an object, the verb must be said TWICE — once with the object, once before 得: 他说汉语说得很好 (he speaks Chinese well), never 他说得很好汉语 or 他说汉语得很好. Second, to negate a degree complement, put 不 (or 没) INSIDE the complement, after 得, not before the verb: 他跑得不快 (he doesn't run fast), not 他不跑得快. The deciding question: does the verb have an object attached — if so, repeat the verb before 得; and where does the negative belong — always after 得, describing the complement itself, never in front of the main verb.",id:"Pelengkap 得 (lihat juga poin perbandingan 的/得/地) menjelaskan seberapa baik, seberapa banyak, atau sejauh mana suatu tindakan terjadi: 他跑得很快 (dia berlari sangat cepat). Ada dua aturan tambahan yang penting saat kata kerjanya punya objek. Pertama, jika ada objek, kata kerjanya harus disebutkan DUA KALI — sekali dengan objeknya, sekali lagi sebelum 得: 他说汉语说得很好 (dia berbicara bahasa Mandarin dengan baik), bukan 他说得很好汉语 atau 他说汉语得很好. Kedua, untuk menegasikan pelengkap tingkat, letakkan 不 (atau 没) DI DALAM pelengkapnya, setelah 得, bukan sebelum kata kerjanya: 他跑得不快 (dia berlari tidak cepat), bukan 他不跑得快. Pertanyaan penentu: apakah kata kerjanya punya objek — jika ya, ulangi kata kerjanya sebelum 得; dan di mana letak negasinya — selalu setelah 得, menjelaskan pelengkapnya sendiri, tidak pernah di depan kata kerja utama."},examples:[{s:"他说汉语说得很流利。",p:"tā shuō hàn yǔ shuō de hěn liú lì",en:"He speaks Chinese very fluently.",id:"Dia berbicara bahasa Mandarin dengan sangat lancar."},{s:"我今天跑得不快，有点儿累。",p:"wǒ jīn tiān pǎo de bú kuài, yǒu diǎnr lèi",en:"I didn't run fast today, I'm a bit tired.",id:"Hari ini saya lari tidak cepat, agak capek."},{s:"她唱歌唱得比我好。",p:"tā chàng gē chàng de bǐ wǒ hǎo",en:"She sings better than I do.",id:"Dia bernyanyi lebih baik daripada saya."}],mistake:{wrong:"他说得很好汉语。",right:"他说汉语说得很好。",note:{en:"When the verb takes an object, the verb must be repeated before 得 — the object attaches to the first occurrence, and the degree complement follows the second.",id:"Saat kata kerjanya punya objek, kata kerjanya harus diulang sebelum 得 — objeknya menempel pada kata kerja yang pertama, dan pelengkap tingkatnya mengikuti kata kerja yang kedua."}}},{id:"yuelaiyue",band:"3",fn:"time",pattern:"越来越 + Adjective/Verb  |  越 + Clause A + 越 + Clause B",title:{en:"越来越 (yuè lái yuè) 'more and more' vs 越...越... (yuè...yuè...) 'the more...the more...'",id:"越来越 (yuè lái yuè) 'makin lama makin' vs 越...越... (yuè...yuè...) 'semakin...semakin...'"},explanation:{en:"Both patterns use 越 (yuè, 'increasingly') but describe different kinds of change. 越来越 + adjective/verb tracks a SINGLE thing getting more so over time: 天气越来越冷 (the weather is getting colder and colder). 越...越... links TWO clauses where one thing changing causes another to change in step: 越学越有意思 (the more you study it, the more interesting it gets), 他越说越生气 (the more he talked, the angrier he got) — the same subject usually does both halves. The deciding question: is only one thing changing over time on its own (→越来越 + one adjective/verb), or does a change in one thing drive a matching change in another (→越 A 越 B, two clauses)? Note 越来越 never needs a second 越 — 越来越来越冷 is wrong; that double structure belongs only to 越...越....",id:"Kedua pola ini memakai 越 (yuè, 'makin/semakin'), tapi menggambarkan jenis perubahan yang berbeda. 越来越 + kata sifat/kata kerja melacak SATU hal yang makin lama makin begitu: 天气越来越冷 (cuacanya makin lama makin dingin). 越...越... menghubungkan DUA klausa di mana perubahan pada satu hal membuat hal lain ikut berubah: 越学越有意思 (semakin dipelajari, semakin menarik), 他越说越生气 (semakin dia bicara, semakin dia marah) — subjeknya biasanya sama untuk kedua bagian. Pertanyaan penentu: apakah hanya satu hal yang berubah seiring waktu dengan sendirinya (→越来越 + satu kata sifat/kerja), atau perubahan pada satu hal memicu perubahan yang sepadan pada hal lain (→越 A 越 B, dua klausa)? Perlu diingat, 越来越 tidak pernah butuh 越 kedua — 越来越来越冷 salah; struktur ganda itu khusus milik 越...越...."},examples:[{s:"天气越来越冷了，你要多穿点儿衣服。",p:"tiān qì yuè lái yuè lěng le, nǐ yào duō chuān diǎnr yī fu",en:"The weather is getting colder and colder — you should wear more clothes.",id:"Cuacanya makin lama makin dingin, kamu harus pakai baju lebih tebal."},{s:"汉语越学越有意思。",p:"hàn yǔ yuè xué yuè yǒu yì si",en:"The more you study Chinese, the more interesting it gets.",id:"Bahasa Mandarin, semakin dipelajari semakin menarik."},{s:"他越解释，大家越糊涂，最后越来越没人听得懂。",p:"tā yuè jiě shì, dà jiā yuè hú tu, zuì hòu yuè lái yuè méi rén tīng de dǒng",en:"The more he explained, the more confused everyone got, until in the end fewer and fewer people could understand him.",id:"Semakin dia menjelaskan, semakin bingung semua orang, sampai akhirnya makin lama makin sedikit orang yang mengerti."}],mistake:{wrong:"这个城市越来越越大。",right:"这个城市越来越大。",note:{en:"越来越 only takes one adjective/verb after it — don't add a second 越 (that double-越 pattern belongs to the separate 越...越... construction for two linked clauses).",id:"越来越 hanya diikuti satu kata sifat/kerja — jangan tambahkan 越 kedua (pola 越 ganda itu milik konstruksi terpisah 越...越... untuk dua klausa yang saling terkait)."}}},{id:"yibian-yibian",band:"3",fn:"time",pattern:"Subject + 一边 + Verb1 + 一边 + Verb2",title:{en:"一边...一边... (yìbiān...yìbiān...) — doing two things at the same time",id:"一边...一边... (yìbiān...yìbiān...) — melakukan dua hal sekaligus"},explanation:{en:"一边 + Verb1 + 一边 + Verb2 says the same subject does two actions simultaneously: 我一边吃饭一边看电视 (I eat while watching TV). Both verbs need to be things a single person can physically do at once (walking and talking, eating and watching) — it doesn't work for two states that can't overlap, or for a sequence of one-after-another actions (for that, use 先...然后... instead). The subject only appears once, before the first 一边, and both actions share it — 我一边吃饭，他一边看电视 (mixing two different subjects) is wrong; that's just two separate simultaneous sentences, not one 一边...一边... sentence. The deciding question: are these two actions genuinely happening at once, performed by the very same person, and can a person's body actually do both at the same moment?",id:"一边 + Kata Kerja1 + 一边 + Kata Kerja2 menyatakan bahwa subjek yang sama melakukan dua tindakan secara bersamaan: 我一边吃饭一边看电视 (saya makan sambil menonton TV). Kedua kata kerjanya harus merupakan hal yang bisa dilakukan satu orang secara fisik sekaligus (berjalan dan bicara, makan dan menonton) — pola ini tidak cocok untuk dua keadaan yang tidak mungkin tumpang tindih, atau untuk tindakan berurutan satu demi satu (untuk itu, gunakan 先...然后... sebagai gantinya). Subjeknya hanya muncul sekali, sebelum 一边 yang pertama, dan kedua tindakan itu berbagi subjek yang sama — 我一边吃饭，他一边看电视 (mencampur dua subjek yang berbeda) salah; itu cuma dua kalimat terpisah yang kebetulan bersamaan, bukan satu kalimat 一边...一边.... Pertanyaan penentu: apakah kedua tindakan ini benar-benar terjadi bersamaan, dilakukan oleh orang yang sama persis, dan apakah tubuh seseorang memang bisa melakukan keduanya di saat yang sama?"},examples:[{s:"他一边听音乐一边做作业。",p:"tā yì biān tīng yīn yuè yì biān zuò zuò yè",en:"He does his homework while listening to music.",id:"Dia mengerjakan PR sambil mendengarkan musik."},{s:"我们一边走一边聊天吧。",p:"wǒ men yì biān zǒu yì biān liáo tiān ba",en:"Let's walk and chat at the same time.",id:"Kita jalan sambil ngobrol, yuk."},{s:"她一边喝咖啡，一边看着窗外，一边想着明天的考试。",p:"tā yì biān hē kā fēi, yì biān kàn zhe chuāng wài, yì biān xiǎng zhe míng tiān de kǎo shì",en:"She drinks her coffee, looks out the window, and thinks about tomorrow's exam, all at the same time.",id:"Dia minum kopi, sambil melihat ke luar jendela, sambil memikirkan ujian besok."}],mistake:{wrong:"我一边吃饭，他一边看电视。",right:"我吃饭的时候，他在看电视。",note:{en:"一边...一边... needs a single shared subject doing both actions — to describe two different people doing different things at the same time, use ...的时候 or 同时 instead, not 一边...一边....",id:"一边...一边... membutuhkan satu subjek yang sama yang melakukan kedua tindakan — untuk menggambarkan dua orang berbeda yang melakukan hal berbeda pada saat bersamaan, gunakan ...的时候 atau 同时, bukan 一边...一边...."}}},{id:"chule-yiwai",band:"3",fn:"connecting",pattern:"除了 + A + 以外, + 都/也/还 + B",title:{en:"除了...以外 (chúle...yǐwài) — 'except for' vs 'besides, in addition to'",id:"除了...以外 (chúle...yǐwài) — 'kecuali' vs 'selain itu, di samping itu'"},explanation:{en:"除了 A 以外 introduces A as either an EXCEPTION or an ADDITION, and the word that follows in the second clause is what tells you which: pair it with 都/全 (all) to mean 'except for A, everything else B' — 除了小明以外，大家都来了 (everyone came except Xiaoming); pair it with 也/还 (also/too) to mean 'besides A, B (too)' — 除了英语以外，他还会说法语 (besides English, he can also speak French). 以外 can be dropped in casual speech (除了小明，大家都来了), but 除了 itself is required. The deciding question: does what follows 除了...以外 exclude that item from a group (→都/全), or add another item on top of it (→也/还)? Getting the second-clause word wrong flips the entire meaning of the sentence.",id:"除了 A 以外 memperkenalkan A sebagai PENGECUALIAN atau TAMBAHAN, dan kata yang muncul di klausa kedua menentukan mana yang dimaksud: pasangkan dengan 都/全 (semua) untuk berarti 'kecuali A, semua yang lain B' — 除了小明以外，大家都来了 (semua orang datang kecuali Xiaoming); pasangkan dengan 也/还 (juga/pun) untuk berarti 'selain A, B (juga)' — 除了英语以外，他还会说法语 (selain bahasa Inggris, dia juga bisa berbahasa Prancis). 以外 bisa dihilangkan dalam percakapan santai (除了小明，大家都来了), tapi 除了 sendiri wajib ada. Pertanyaan penentu: apakah hal setelah 除了...以外 itu dikecualikan dari suatu kelompok (→都/全), atau ditambahkan di atas hal lain (→也/还)? Salah memilih kata di klausa kedua membalikkan makna seluruh kalimat."},examples:[{s:"除了小明以外，大家都来了。",p:"chú le xiǎo míng yǐ wài, dà jiā dōu lái le",en:"Everyone came except Xiaoming.",id:"Semua orang datang kecuali Xiaoming."},{s:"除了英语以外，他还会说法语。",p:"chú le yīng yǔ yǐ wài, tā hái huì shuō fǎ yǔ",en:"Besides English, he can also speak French.",id:"Selain bahasa Inggris, dia juga bisa berbahasa Prancis."},{s:"除了打篮球以外，他也喜欢游泳，可是除了他以外，我们都不喜欢运动。",p:"chú le dǎ lán qiú yǐ wài, tā yě xǐ huan yóu yǒng, kě shì chú le tā yǐ wài, wǒ men dōu bù xǐ huan yùn dòng",en:"Besides playing basketball, he also likes swimming, but except for him, none of us like sports.",id:"Selain main basket, dia juga suka berenang, tapi kecuali dia, kami semua tidak suka olahraga."}],mistake:{wrong:"除了小明以外，大家也来了。",right:"除了小明以外，大家都来了。",note:{en:"To exclude Xiaoming from the group that came, the second clause needs 都 (everyone else did) — 也 would instead mean Xiaoming came too, which contradicts 'except for'.",id:"Untuk mengecualikan Xiaoming dari kelompok yang datang, klausa kedua membutuhkan 都 (semua yang lain datang) — 也 justru berarti Xiaoming juga datang, yang bertentangan dengan makna 'kecuali'."}}},{id:"budan-erqie",band:"3",fn:"connecting",pattern:"不但 + Clause A, 而且(也/还) + Clause B",title:{en:"不但...而且... (búdàn...érqiě...) — 'not only...but also...'",id:"不但...而且... (búdàn...érqiě...) — 'tidak hanya...tetapi juga...'"},explanation:{en:"不但...而且... stacks a second, stronger or additional fact on top of the first — 'not only A, but also B', where B usually escalates or reinforces A: 她不但漂亮，而且很聪明 (she's not only pretty, but also very smart). If both clauses share the same subject, 不但 comes AFTER the subject (她不但漂亮...); if the two clauses have different subjects, 不但 comes BEFORE its own subject, right at the start of the clause: 不但他去了，而且他妹妹也去了 (not only did he go, but his sister went too). 而且 is often reinforced with 也 or 还 right after it. The deciding question: is the second fact simply additional/stronger information about the same topic (→不但...而且...), and does each clause have its own subject or share one — that decides where exactly 不但 sits.",id:"不但...而且... menumpuk fakta kedua yang lebih kuat atau tambahan di atas fakta pertama — 'tidak hanya A, tetapi juga B', di mana B biasanya menguatkan atau menambah A: 她不但漂亮，而且很聪明 (dia tidak hanya cantik, tetapi juga sangat pintar). Kalau kedua klausa berbagi subjek yang sama, 不但 diletakkan SETELAH subjek (她不但漂亮...); kalau kedua klausa punya subjek yang berbeda, 不但 diletakkan SEBELUM subjeknya sendiri, tepat di awal klausa: 不但他去了，而且他妹妹也去了 (bukan hanya dia yang pergi, adik perempuannya juga ikut pergi). 而且 sering diperkuat dengan 也 atau 还 tepat setelahnya. Pertanyaan penentu: apakah fakta kedua itu sekadar informasi tambahan/lebih kuat tentang topik yang sama (→不但...而且...), dan apakah setiap klausa punya subjeknya sendiri atau berbagi satu — itu yang menentukan tepatnya di mana 不但 diletakkan."},examples:[{s:"她不但漂亮，而且很聪明。",p:"tā bú dàn piào liang, ér qiě hěn cōng ming",en:"She's not only pretty, but also very smart.",id:"Dia tidak hanya cantik, tetapi juga sangat pintar."},{s:"不但他去了，而且他妹妹也去了。",p:"bú dàn tā qù le, ér qiě tā mèi mei yě qù le",en:"Not only did he go, but his sister went too.",id:"Bukan hanya dia yang pergi, adik perempuannya juga ikut pergi."},{s:"这家饭馆不但便宜，而且菜做得还特别好吃。",p:"zhè jiā fàn guǎn bú dàn pián yi, ér qiě cài zuò de hái tè bié hǎo chī",en:"This restaurant isn't only cheap, its food is also especially delicious.",id:"Restoran ini tidak hanya murah, masakannya juga sangat enak."}],mistake:{wrong:"他不但去了，而且不但他妹妹也去了。",right:"不但他去了，而且他妹妹也去了。",note:{en:"When the two clauses have different subjects (he vs. his sister), 不但 belongs at the very start of its clause, before that clause's own subject — not repeated or placed after the first subject.",id:"Ketika kedua klausa punya subjek berbeda (dia vs adiknya), 不但 diletakkan tepat di awal klausanya, sebelum subjek klausa itu sendiri — bukan diulang atau diletakkan setelah subjek pertama."}}},{id:"yinwei-suoyi-youyu",band:"3",fn:"connecting",pattern:"因为 + Cause, 所以 + Result   |   由于 + Cause, (因此/所以) + Result",title:{en:"因为...所以... (yīnwèi...suǒyǐ...) vs 由于 (yóuyú) — everyday cause vs formal/written cause",id:"因为...所以... (yīnwèi...suǒyǐ...) vs 由于 (yóuyú) — sebab sehari-hari vs sebab formal/tertulis"},explanation:{en:"因为...所以... is the everyday, spoken way to link a cause and its result — 'because...so...': 因为下雨，所以我们没去公园 (because it rained, we didn't go to the park). In casual speech only one of the pair is often used (just 因为, or just 所以). 由于 (yóuyú) means the same 'because/due to', but is more formal and written — common in news, reports, and official notices — and it pairs more naturally with 因此 or 所以 for the result, and can also open a written sentence where 因为 would sound too conversational: 由于天气原因，航班延误了 (due to weather, the flight was delayed). Unlike 因为, 由于 cannot be used to answer a casual '为什么' question on its own. The deciding question: is this everyday conversation about a concrete, personal reason (→因为...所以...), or a more formal/impersonal explanation, often about a fact, policy, or written report (→由于)?",id:"因为...所以... adalah cara sehari-hari dan lisan untuk menghubungkan sebab dan akibatnya — 'karena...jadi...': 因为下雨，所以我们没去公园 (karena hujan, kami tidak pergi ke taman). Dalam percakapan santai, sering hanya salah satu dari pasangan itu yang dipakai (hanya 因为, atau hanya 所以). 由于 (yóuyú) berarti sama, 'karena/disebabkan oleh', tapi lebih formal dan tertulis — umum dipakai dalam berita, laporan, dan pengumuman resmi — dan lebih wajar dipasangkan dengan 因此 atau 所以 untuk akibatnya, serta bisa membuka kalimat tertulis di mana 因为 akan terdengar terlalu santai: 由于天气原因，航班延误了 (karena alasan cuaca, penerbangannya tertunda). Berbeda dengan 因为, 由于 tidak bisa dipakai sendirian untuk menjawab pertanyaan santai '为什么'. Pertanyaan penentu: apakah ini percakapan sehari-hari tentang alasan yang konkret dan personal (→因为...所以...), atau penjelasan yang lebih formal/impersonal, sering tentang fakta, kebijakan, atau laporan tertulis (→由于)?"},examples:[{s:"因为今天下雨，所以我们没去公园。",p:"yīn wèi jīn tiān xià yǔ, suǒ yǐ wǒ men méi qù gōng yuán",en:"Because it rained today, we didn't go to the park.",id:"Karena hari ini hujan, kami tidak pergi ke taman."},{s:"由于天气原因，航班延误了三个小时。",p:"yóu yú tiān qì yuán yīn, háng bān yán wù le sān gè xiǎo shí",en:"Due to weather conditions, the flight was delayed by three hours.",id:"Karena alasan cuaca, penerbangannya tertunda selama tiga jam."},{s:"由于交通堵塞，他迟到了，因为这样，老板对他很不满意。",p:"yóu yú jiāo tōng dǔ sè, tā chí dào le, yīn wèi zhè yàng, lǎo bǎn duì tā hěn bù mǎn yì",en:"Because of the traffic jam, he was late; because of that, his boss was quite unhappy with him.",id:"Karena kemacetan lalu lintas, dia terlambat; karena itu, bosnya cukup tidak puas dengannya."}],mistake:{wrong:"你今天为什么没来？由于我生病了。",right:"你今天为什么没来？因为我生病了。",note:{en:"由于 is too formal/written to answer a casual spoken 'why' question about yourself — everyday personal reasons use 因为, keeping 由于 for formal or written explanations.",id:"由于 terlalu formal/tertulis untuk menjawab pertanyaan 'kenapa' lisan yang santai tentang dirimu sendiri — alasan pribadi sehari-hari memakai 因为, sedangkan 由于 disimpan untuk penjelasan formal atau tertulis."}}},{id:"ruguo-jiu",band:"3",fn:"connecting",pattern:"如果/要是 + Condition, (那么) 就 + Result",title:{en:"如果/要是...就... (rúguǒ/yàoshi...jiù...) — 'if...then...'",id:"如果/要是...就... (rúguǒ/yàoshi...jiù...) — 'kalau...maka...'"},explanation:{en:"如果 (rúguǒ) and 要是 (yàoshi) both mean 'if' and are largely interchangeable, with 就 in the second clause meaning 'then': 如果明天下雨，我们就不去了 (if it rains tomorrow, then we won't go). 要是 is more common in casual spoken Chinese, while 如果 works in both speech and writing and pairs more naturally with a formal 那么 (then) before 就 in longer sentences. Either word can be dropped and the conditional meaning still comes through from context and 就 alone, especially in quick spoken exchanges: 你不说，我就不知道 (if you don't say, [then] I won't know). The deciding question: am I stating a hypothetical condition and its consequence — pick either 如果 or 要是 for the 'if' clause (要是 leaning casual), and don't forget 就 to introduce the 'then' result, since 就 is what actually signals the consequence.",id:"如果 (rúguǒ) dan 要是 (yàoshi) sama-sama berarti 'kalau/jika' dan sebagian besar bisa saling menggantikan, dengan 就 di klausa kedua berarti 'maka': 如果明天下雨，我们就不去了 (kalau besok hujan, maka kami tidak akan pergi). 要是 lebih umum dalam bahasa Mandarin lisan yang santai, sementara 如果 cocok dipakai baik dalam percakapan maupun tulisan dan lebih wajar dipasangkan dengan 那么 (maka) yang formal sebelum 就 dalam kalimat yang lebih panjang. Salah satu katanya bisa dihilangkan dan makna kondisionalnya tetap tersampaikan dari konteks dan 就 saja, terutama dalam percakapan cepat: 你不说，我就不知道 (kalau kamu tidak bilang, [maka] saya tidak akan tahu). Pertanyaan penentu: apakah saya sedang menyatakan syarat andaikata dan akibatnya — pilih 如果 atau 要是 untuk klausa 'kalau' (要是 lebih santai), dan jangan lupa 就 untuk memperkenalkan akibat 'maka', karena 就 lah yang sebenarnya menandai akibatnya."},examples:[{s:"如果明天下雨，我们就不去爬山了。",p:"rú guǒ míng tiān xià yǔ, wǒ men jiù bú qù pá shān le",en:"If it rains tomorrow, we won't go hiking.",id:"Kalau besok hujan, kami tidak akan naik gunung."},{s:"要是你有时间，就来我家玩儿吧。",p:"yào shi nǐ yǒu shí jiān, jiù lái wǒ jiā wánr ba",en:"If you have time, come over to my place.",id:"Kalau kamu punya waktu, mainlah ke rumah saya."},{s:"如果这个方法不行，那么我们就得换一个办法了。",p:"rú guǒ zhè ge fāng fǎ bù xíng, nà me wǒ men jiù děi huàn yí gè bàn fǎ le",en:"If this method doesn't work, then we'll have to try a different approach.",id:"Kalau cara ini tidak berhasil, maka kita harus mengganti cara lain."}],mistake:{wrong:"如果明天下雨，我们不去爬山了。",right:"如果明天下雨，我们就不去爬山了。",note:{en:"如果 sets up the condition, but 就 is what actually signals the consequence in the second clause — leaving it out makes the two clauses feel disconnected rather than if-then.",id:"如果 menyiapkan syaratnya, tapi 就 lah yang benar-benar menandai akibatnya di klausa kedua — menghilangkannya membuat kedua klausa terasa terpisah, bukan hubungan kalau-maka."}}},{id:"suiran-danshi",band:"3",fn:"connecting",pattern:"虽然 + Clause A, 但是/可是 + Clause B",title:{en:"虽然...但是... (suīrán...dànshì...) — 'although...but...'",id:"虽然...但是... (suīrán...dànshì...) — 'meskipun...tetapi...'"},explanation:{en:"虽然...但是... links a concession and a contrasting point — 'although A, but B', where B pushes back against what A would normally lead you to expect: 虽然他很累，但是他还是去上班了 (although he was very tired, he still went to work). Unlike English 'although...but' (which is redundant and avoided), Chinese not only allows both words together, it strongly prefers them — 虽然 alone without 但是/可是 can sound like an unfinished thought. 可是 works interchangeably with 但是 here, just slightly more conversational. The deciding question: does the second half go against the natural expectation set up by the first half? If so, keep both 虽然 and 但是/可是 — don't drop the second one the way English drops 'but' after 'although'.",id:"虽然...但是... menghubungkan sebuah pengakuan dengan poin yang berlawanan — 'meskipun A, tetapi B', di mana B melawan apa yang secara wajar diharapkan dari A: 虽然他很累，但是他还是去上班了 (meskipun dia sangat lelah, dia tetap pergi bekerja). Berbeda dengan bahasa Indonesia/Inggris yang biasanya cukup pakai salah satu ('meskipun' saja, atau 'tetapi' saja), bahasa Mandarin tidak hanya mengizinkan keduanya dipakai bersamaan, tapi justru lebih menyukainya — 虽然 sendirian tanpa 但是/可是 bisa terdengar seperti kalimat yang belum selesai. 可是 bisa dipakai bergantian dengan 但是 di sini, hanya sedikit lebih santai. Pertanyaan penentu: apakah bagian kedua berlawanan dengan harapan wajar yang dibentuk oleh bagian pertama? Jika ya, pertahankan 虽然 maupun 但是/可是 — jangan hilangkan salah satunya seperti kebiasaan bahasa Indonesia/Inggris yang cukup pakai satu kata saja."},examples:[{s:"虽然他很累，但是他还是去上班了。",p:"suī rán tā hěn lèi, dàn shì tā hái shi qù shàng bān le",en:"Although he was very tired, he still went to work.",id:"Meskipun dia sangat lelah, dia tetap pergi bekerja."},{s:"这道题虽然难，可是我还是做出来了。",p:"zhè dào tí suī rán nán, kě shì wǒ hái shi zuò chū lái le",en:"Although this problem was hard, I still solved it.",id:"Soal ini meskipun sulit, saya tetap berhasil menyelesaikannya."},{s:"虽然他中文说得不错，但是写汉字还是有点儿困难。",p:"suī rán tā zhōng wén shuō de bú cuò, dàn shì xiě hàn zì hái shi yǒu diǎnr kùn nan",en:"Although he speaks Chinese pretty well, writing characters is still a bit hard for him.",id:"Meskipun bahasa Mandarinnya cukup lancar, menulis karakter Han masih agak sulit baginya."}],mistake:{wrong:"虽然他很累，他还是去上班了。",right:"虽然他很累，但是他还是去上班了。",note:{en:"Chinese keeps both halves of the pair — dropping 但是/可是 the way English drops 'but' after 'although' makes the sentence sound unfinished; 虽然 alone isn't enough.",id:"Bahasa Mandarin mempertahankan kedua kata pasangan ini — menghilangkan 但是/可是 seperti kebiasaan bahasa Indonesia yang cukup 'meskipun' saja membuat kalimatnya terasa belum selesai; 虽然 saja tidak cukup."}}},{id:"lian-dou-ye",band:"3",fn:"connecting",pattern:"连 + Extreme example + 都/也 + (不/没) + Verb",title:{en:"连...都/也... (lián...dōu/yě...) — 'even...'",id:"连...都/也... (lián...dōu/yě...) — 'bahkan...'"},explanation:{en:"连 fronts an extreme or surprising example — the least likely case — and 都 or 也 right after it emphasizes 'even this counts': 连小孩儿都懂 (even a small child understands [this] — so it must be really simple), 他连一句话都没说 (he didn't even say a single word). The example after 连 is usually the most extreme point on some scale (the youngest, the smallest amount, the easiest task) to make the claim about everything else even stronger by implication. 都 and 也 are largely interchangeable here; 都 is slightly more common. The deciding question: am I picking the single most surprising/extreme case to prove a broader point applies to everything else too? If so, front it with 连 and follow with 都/也 — a bare 都 or 也 without 连 loses that 'even' emphasis and just becomes a plain 'all/also' statement.",id:"连 memajukan contoh yang ekstrem atau mengejutkan — kasus yang paling tidak mungkin — dan 都 atau 也 tepat setelahnya menegaskan 'bahkan ini pun termasuk': 连小孩儿都懂 (bahkan anak kecil pun mengerti [ini] — jadi pasti sangat mudah), 他连一句话都没说 (dia bahkan tidak mengucapkan satu kata pun). Contoh setelah 连 biasanya adalah titik paling ekstrem dalam suatu skala (yang paling muda, jumlah paling sedikit, tugas paling mudah) untuk membuat klaimnya tentang hal-hal lain terasa lebih kuat lagi secara tersirat. 都 dan 也 di sini sebagian besar bisa saling menggantikan; 都 sedikit lebih umum. Pertanyaan penentu: apakah saya memilih satu kasus paling mengejutkan/ekstrem untuk membuktikan bahwa hal yang lebih luas juga berlaku untuk semua yang lain? Jika ya, majukan dengan 连 dan ikuti dengan 都/也 — 都 atau 也 saja tanpa 连 kehilangan penekanan 'bahkan' itu dan hanya menjadi pernyataan 'semua/juga' yang biasa."},examples:[{s:"这个问题连小孩儿都懂。",p:"zhè ge wèn tí lián xiǎo háir dōu dǒng",en:"Even a small child understands this question.",id:"Pertanyaan ini bahkan anak kecil pun mengerti."},{s:"他连一句话都没说就走了。",p:"tā lián yí jù huà dōu méi shuō jiù zǒu le",en:"He left without even saying a single word.",id:"Dia pergi tanpa mengucapkan satu kata pun."},{s:"这道题太难了，连老师也不知道怎么解。",p:"zhè dào tí tài nán le, lián lǎo shī yě bù zhī dào zěn me jiě",en:"This problem is so hard that even the teacher doesn't know how to solve it.",id:"Soal ini terlalu sulit, bahkan gurunya pun tidak tahu cara menyelesaikannya."}],mistake:{wrong:"他连一句话没说就走了。",right:"他连一句话都没说就走了。",note:{en:"连 needs 都 or 也 right after the extreme example to complete the 'even' emphasis — 连 alone, without 都/也, is left hanging.",id:"连 membutuhkan 都 atau 也 tepat setelah contoh ekstremnya untuk melengkapi penekanan 'bahkan' — 连 saja tanpa 都/也 terasa menggantung."}}},{id:"shenme-dou-shei-dou",band:"3",fn:"describing",pattern:"什么/谁/哪儿/怎么 + 都/也 + (不/没) + Verb",title:{en:"什么都/谁都... (shénme dōu/shéi dōu...) — question words as 'everything/everyone/anywhere'",id:"什么都/谁都... (shénme dōu/shéi dōu...) — kata tanya sebagai 'segalanya/semua orang/di mana saja'"},explanation:{en:"Question words like 什么 (what), 谁 (who), 哪儿 (where), and 怎么 (how) turn into universal statements — 'everything, everyone, everywhere, no matter how' — when followed by 都 or 也, instead of being used to actually ask something: 他什么都吃 (he eats everything/anything), 谁都可以来 (anyone/everyone can come), 我哪儿都没去 (I didn't go anywhere). Add 不 or 没 before the verb to make it a universal negative: 我什么都不知道 (I don't know anything at all). The deciding question: is the question word actually asking for specific information (→ needs 吗/呢 and rising question intonation, no 都/也), or is it standing in for 'no matter what/who/where' as part of a sweeping statement (→ follow it with 都 or 也, no question mark)? Without 都/也 right after, 什么/谁/哪儿 default back to being real questions.",id:"Kata tanya seperti 什么 (apa), 谁 (siapa), 哪儿 (di mana), dan 怎么 (bagaimana) berubah menjadi pernyataan universal — 'segalanya, semua orang, di mana saja, bagaimanapun' — ketika diikuti 都 atau 也, alih-alih dipakai untuk benar-benar bertanya: 他什么都吃 (dia makan apa saja/segalanya), 谁都可以来 (siapa saja/semua orang boleh datang), 我哪儿都没去 (saya tidak pergi ke mana-mana). Tambahkan 不 atau 没 sebelum kata kerja untuk membuatnya jadi negatif universal: 我什么都不知道 (saya sama sekali tidak tahu apa-apa). Pertanyaan penentu: apakah kata tanya ini benar-benar menanyakan informasi tertentu (→ butuh 吗/呢 dan intonasi tanya naik, tanpa 都/也), atau berfungsi sebagai 'apa pun/siapa pun/di mana pun' dalam pernyataan yang menyeluruh (→ ikuti dengan 都 atau 也, tanpa tanda tanya)? Tanpa 都/也 tepat setelahnya, 什么/谁/哪儿 kembali menjadi pertanyaan sungguhan."},examples:[{s:"他什么都吃，一点儿都不挑食。",p:"tā shén me dōu chī, yì diǎnr dōu bù tiāo shí",en:"He eats everything — not picky at all.",id:"Dia makan apa saja, sama sekali tidak pilih-pilih makanan."},{s:"这个消息谁都知道了。",p:"zhè ge xiāo xi shéi dōu zhī dào le",en:"Everyone already knows this news.",id:"Kabar ini semua orang sudah tahu."},{s:"我今天哪儿都不想去，只想在家什么都不做。",p:"wǒ jīn tiān nǎr dōu bù xiǎng qù, zhǐ xiǎng zài jiā shén me dōu bú zuò",en:"I don't want to go anywhere today, I just want to stay home and do nothing at all.",id:"Hari ini saya tidak ingin pergi ke mana-mana, saya cuma ingin di rumah dan tidak melakukan apa-apa."}],mistake:{wrong:"他什么吃。",right:"他什么都吃。",note:{en:"什么 alone just asks 'what' — to turn it into 'everything/anything', it needs 都 (or 也) right after it before the verb.",id:"什么 saja hanya bertanya 'apa' — untuk mengubahnya menjadi 'apa saja/segalanya', dibutuhkan 都 (atau 也) tepat setelahnya, sebelum kata kerja."}}},{id:"shi-de-emphasis",band:"3",fn:"past",pattern:"Subject + 是 + [Time/Place/Manner/Agent] + Verb + 的",title:{en:"是...的 (shì...de) — emphasizing the time, place, or manner of a past event",id:"是...的 (shì...de) — menekankan waktu, tempat, atau cara suatu kejadian di masa lalu"},explanation:{en:"When both speaker and listener already know THAT something happened, 是...的 zooms in to emphasize the circumstances — when, where, how, or by whom it happened — rather than the bare fact that it happened (that's what plain 了 is for): 我是昨天到的 (it was YESTERDAY that I arrived — emphasizing when), 他是坐飞机来的 (it was BY PLANE that he came — emphasizing how). 是 can often be dropped in casual speech (especially in statements, less so with negation), but 的 at the end is required. Because the event is already known to have happened, 了 does NOT appear inside this pattern — 我是昨天到了的 is wrong; 是...的 replaces the need for 了 entirely. The deciding question: is the fact that it happened already established/obvious, and do I want to spotlight WHEN/WHERE/HOW/WHO specifically (→是...的)? If the fact itself is new information, use plain 了 instead.",id:"Ketika pembicara dan lawan bicara sudah sama-sama tahu BAHWA sesuatu terjadi, 是...的 menyorot keadaan sekitarnya — kapan, di mana, bagaimana, atau oleh siapa itu terjadi — bukan sekadar fakta bahwa itu terjadi (itu tugas 了 biasa): 我是昨天到的 (justru KEMARIN saya tiba — menekankan kapan), 他是坐飞机来的 (justru NAIK PESAWAT dia datang — menekankan caranya). 是 sering bisa dihilangkan dalam percakapan santai (terutama dalam pernyataan, lebih jarang dalam negasi), tapi 的 di akhir wajib ada. Karena kejadiannya sudah diketahui terjadi, 了 TIDAK muncul di dalam pola ini — 我是昨天到了的 salah; 是...的 sepenuhnya menggantikan kebutuhan akan 了. Pertanyaan penentu: apakah fakta bahwa itu terjadi sudah diketahui/jelas, dan apakah saya ingin menyorot KAPAN/DI MANA/BAGAIMANA/SIAPA secara spesifik (→是...的)? Kalau faktanya sendiri adalah informasi baru, gunakan 了 biasa sebagai gantinya."},examples:[{s:"我是昨天到的，不是今天。",p:"wǒ shì zuó tiān dào de, bú shì jīn tiān",en:"It was yesterday that I arrived, not today.",id:"Saya tiba kemarin, bukan hari ini."},{s:"他是坐飞机来的。",p:"tā shì zuò fēi jī lái de",en:"He came by plane.",id:"Dia datang naik pesawat."},{s:"这本书是我在北京买的，是去年买的。",p:"zhè běn shū shì wǒ zài běi jīng mǎi de, shì qù nián mǎi de",en:"I bought this book in Beijing — I bought it last year.",id:"Buku ini saya beli di Beijing, saya belinya tahun lalu."}],mistake:{wrong:"我是昨天到了的。",right:"我是昨天到的。",note:{en:"了 doesn't appear inside 是...的 — the pattern already marks the event as a known, completed fact, so 的 alone closes the sentence, without an extra 了.",id:"了 tidak muncul di dalam pola 是...的 — pola ini sudah menandai kejadiannya sebagai fakta yang diketahui dan selesai, jadi 的 saja yang menutup kalimat, tanpa tambahan 了."}}},{id:"kuaiyao-jiuyao-le",band:"3",fn:"time",pattern:"快(要) + Verb/Adjective + 了   |   (Time) + 就要 + Verb + 了",title:{en:"快要...了 (kuàiyào...le) vs 就要...了 (jiùyào...le) — 'about to' happen soon",id:"快要...了 (kuàiyào...le) vs 就要...了 (jiùyào...le) — 'hampir/segera' terjadi"},explanation:{en:"Both patterns sandwich the verb between a 'soon' word and a final 了 to mean something is about to happen: 电影快要开始了 (the movie is about to start), 火车就要开了 (the train is about to leave). 快(要) emphasizes that the moment is drawing near from the speaker's present vantage point, and doesn't usually combine with a specific time word — 快要明天了 sounds odd. 就要 works the same way but CAN be preceded by a specific time word to say exactly when: 他明天就要走了 (he's leaving [as soon as] tomorrow) — that combination (specific time + 就要) is not natural with 快要. The deciding question: do I have a specific time point to state before it (→就要, since it tolerates a time word in front), or am I just saying 'soon' in general, from right now (→快 or 快要, either works)? Both need the closing 了 — dropping it turns the sentence into a plain statement about the future rather than 'right on the verge'.",id:"Kedua pola ini mengapit kata kerja di antara kata 'segera' dan 了 di akhir untuk menyatakan sesuatu akan segera terjadi: 电影快要开始了 (filmnya hampir mulai), 火车就要开了 (keretanya hampir berangkat). 快(要) menekankan bahwa momen itu semakin dekat dari sudut pandang pembicara saat ini, dan biasanya tidak digabung dengan kata waktu yang spesifik — 快要明天了 terdengar aneh. 就要 bekerja dengan cara yang sama tapi BISA didahului kata waktu yang spesifik untuk menyebutkan persis kapan: 他明天就要走了 (dia akan pergi besok) — gabungan itu (waktu spesifik + 就要) tidak wajar dipakai dengan 快要. Pertanyaan penentu: apakah saya punya titik waktu spesifik yang ingin disebutkan sebelumnya (→就要, karena bisa menerima kata waktu di depannya), atau saya hanya mengatakan 'sebentar lagi' secara umum, dari sekarang (→快 atau 快要, keduanya boleh)? Keduanya membutuhkan 了 penutup — menghilangkannya mengubah kalimat menjadi pernyataan biasa tentang masa depan, bukan 'sudah di ambang terjadi'."},examples:[{s:"电影快要开始了，快进去吧。",p:"diàn yǐng kuài yào kāi shǐ le, kuài jìn qù ba",en:"The movie is about to start, hurry inside.",id:"Filmnya hampir mulai, cepat masuk."},{s:"他明天就要走了。",p:"tā míng tiān jiù yào zǒu le",en:"He's leaving tomorrow.",id:"Dia akan pergi besok."},{s:"别急，火车还没到，不过就快要到了。",p:"bié jí, huǒ chē hái méi dào, bú guò jiù kuài yào dào le",en:"Don't rush, the train hasn't arrived yet, but it's just about to.",id:"Jangan buru-buru, keretanya belum tiba, tapi sebentar lagi tiba."}],mistake:{wrong:"他明天快要走了。",right:"他明天就要走了。",note:{en:"A specific time word like 明天 (tomorrow) pairs with 就要, not 快要 — 快(要) only signals 'soon from now', without naming an exact point in time in front of it.",id:"Kata waktu spesifik seperti 明天 (besok) berpasangan dengan 就要, bukan 快要 — 快(要) hanya menandai 'sebentar lagi dari sekarang', tanpa menyebutkan titik waktu pasti di depannya."}}},{id:"cong-dao",band:"3",fn:"time",pattern:"从 + Start point + 到 + End point",title:{en:"从...到... (cóng...dào...) — 'from...to...' for time and place ranges",id:"从...到... (cóng...dào...) — 'dari...sampai...' untuk rentang waktu dan tempat"},explanation:{en:"从...到... marks a range between a starting point and an ending point — for TIME (从九点到十二点 — from nine to twelve) or for PLACE/distance (从北京到上海 — from Beijing to Shanghai). Both 从 and 到 can also be used separately (从 alone for just a starting point, 到 alone for just a destination/endpoint — 我到北京了, I've arrived in Beijing), but together they frame a clear span with both ends marked, which a lone 从 or 到 can't do. Word order stays fixed: 从 always introduces the earlier/starting point, 到 always the later/ending point — never reversed. The deciding question: do I need to mark BOTH ends of a span (a start and a finish, in time or space) — if so, keep 从 and 到 in that fixed order, matching start-then-end.",id:"从...到... menandai rentang antara titik awal dan titik akhir — untuk WAKTU (从九点到十二点 — dari jam sembilan sampai jam dua belas) atau untuk TEMPAT/jarak (从北京到上海 — dari Beijing sampai Shanghai). 从 dan 到 juga bisa dipakai terpisah (从 sendirian hanya untuk titik awal, 到 sendirian hanya untuk tujuan/titik akhir — 我到北京了, saya sudah tiba di Beijing), tapi bila digabung, keduanya membingkai rentang yang jelas dengan kedua ujungnya ditandai, yang tidak bisa dilakukan oleh 从 atau 到 sendirian. Urutan katanya tetap: 从 selalu memperkenalkan titik yang lebih awal/permulaan, 到 selalu titik yang lebih akhir/penutup — tidak pernah dibalik. Pertanyaan penentu: apakah saya perlu menandai KEDUA ujung suatu rentang (awal dan akhir, dalam waktu atau ruang) — jika ya, pertahankan 从 dan 到 dalam urutan tetap itu, sesuai urutan awal-lalu-akhir."},examples:[{s:"我们从九点上课到十二点。",p:"wǒ men cóng jiǔ diǎn shàng kè dào shí èr diǎn",en:"We have class from nine to twelve.",id:"Kami belajar dari jam sembilan sampai jam dua belas."},{s:"从北京到上海坐火车要多长时间？",p:"cóng běi jīng dào shàng hǎi zuò huǒ chē yào duō cháng shí jiān",en:"How long does it take by train from Beijing to Shanghai?",id:"Dari Beijing ke Shanghai naik kereta butuh berapa lama?"},{s:"从星期一到星期五我都要上班，从早上八点忙到晚上六点。",p:"cóng xīng qī yī dào xīng qī wǔ wǒ dōu yào shàng bān, cóng zǎo shang bā diǎn máng dào wǎn shang liù diǎn",en:"I have to work from Monday to Friday, busy from eight in the morning until six at night.",id:"Dari hari Senin sampai Jumat saya harus bekerja, sibuk dari jam delapan pagi sampai jam enam malam."}],mistake:{wrong:"我们到九点上课从十二点。",right:"我们从九点上课到十二点。",note:{en:"从 always marks the earlier/starting point and 到 always marks the later/ending point — the order can't be swapped, even though English 'from...to' word order might tempt you to reorder them.",id:"从 selalu menandai titik yang lebih awal/permulaan dan 到 selalu menandai titik yang lebih akhir/penutup — urutannya tidak bisa ditukar, meskipun urutan kata 'dari...sampai' dalam bahasa Indonesia bisa menggoda untuk membaliknya."}}},{id:"dui-laishuo",band:"3",fn:"connecting",pattern:"对 + Person/Thing + 来说, + Comment",title:{en:"对...来说 (duì...láishuō) — 'as for..., from ...'s point of view'",id:"对...来说 (duì...láishuō) — 'bagi..., dari sudut pandang...'"},explanation:{en:"对...来说 frames the comment that follows as true specifically from a particular person's, group's, or thing's point of view — it flags that the statement might not hold universally, only for this perspective: 对我来说，学汉语不难 (for me, learning Chinese isn't hard [though it might be hard for others]). It usually opens the sentence, with the person/thing sandwiched between 对 and 来说, followed by a comma and the actual comment. Don't confuse it with 关于/对于 (which introduce a TOPIC being discussed, not a perspective the comment is filtered through) — 对我来说 says 'from my standpoint', while 关于我 would mean 'about me [as a topic]', a very different meaning. The deciding question: is what follows true specifically from this one viewpoint, possibly different for someone else (→对...来说), or is this just naming the topic under discussion (→关于/对于, see that point)?",id:"对...来说 membingkai komentar yang mengikutinya sebagai benar khususnya dari sudut pandang orang, kelompok, atau hal tertentu — menandai bahwa pernyataan itu mungkin tidak berlaku secara universal, hanya untuk perspektif ini: 对我来说，学汉语不难 (bagi saya, belajar bahasa Mandarin tidak sulit [meski mungkin sulit bagi orang lain]). Biasanya pola ini membuka kalimat, dengan orang/hal yang diapit antara 对 dan 来说, diikuti koma lalu komentar sebenarnya. Jangan tertukar dengan 关于/对于 (yang memperkenalkan TOPIK yang sedang dibahas, bukan perspektif yang menyaring komentarnya) — 对我来说 berarti 'dari sudut pandang saya', sedangkan 关于我 berarti 'tentang saya [sebagai topik]', makna yang sangat berbeda. Pertanyaan penentu: apakah hal yang mengikuti itu benar khususnya dari satu sudut pandang ini, yang mungkin berbeda bagi orang lain (→对...来说), atau ini sekadar menyebutkan topik yang sedang dibahas (→关于/对于, lihat poin itu)?"},examples:[{s:"对我来说，学汉语不难，但是写汉字有点儿难。",p:"duì wǒ lái shuō, xué hàn yǔ bù nán, dàn shì xiě hàn zì yǒu diǎnr nán",en:"For me, learning Chinese isn't hard, but writing characters is a bit hard.",id:"Bagi saya, belajar bahasa Mandarin tidak sulit, tapi menulis karakter Han agak sulit."},{s:"对年轻人来说，手机已经是生活中不可缺少的东西了。",p:"duì nián qīng rén lái shuō, shǒu jī yǐ jīng shì shēng huó zhōng bù kě quē shǎo de dōng xi le",en:"For young people, phones are already an indispensable part of life.",id:"Bagi anak muda, ponsel sudah menjadi hal yang tidak bisa lepas dari kehidupan."},{s:"对我来说这个价格太贵了，但是对他来说很便宜。",p:"duì wǒ lái shuō zhè ge jià gé tài guì le, dàn shì duì tā lái shuō hěn pián yi",en:"This price is too expensive for me, but it's cheap for him.",id:"Bagi saya harga ini terlalu mahal, tapi bagi dia murah sekali."}],mistake:{wrong:"关于我来说，学汉语不难。",right:"对我来说，学汉语不难。",note:{en:"'From my point of view' needs 对...来说, not 关于...来说 — 关于 introduces a topic being talked ABOUT, it doesn't combine with 来说 to mean 'from someone's perspective'.",id:"'Dari sudut pandang saya' membutuhkan 对...来说, bukan 关于...来说 — 关于 memperkenalkan topik yang sedang dibicarakan, bukan digabung dengan 来说 untuk berarti 'dari sudut pandang seseorang'."}}},{id:"guanyu-duiyu",band:"3",fn:"connecting",pattern:"关于/对于 + Topic, + Comment   |   Subject + 对于 + Topic + Comment",title:{en:"关于 (guānyú) vs 对于 (duìyú) — introducing a topic: 'about/regarding' vs 'with regard to'",id:"关于 (guānyú) vs 对于 (duìyú) — memperkenalkan topik: 'tentang' vs 'terhadap'"},explanation:{en:"关于 and 对于 both mean roughly 'regarding, about', introducing the topic a sentence is going to discuss, but they attach differently. 关于 + Topic almost always opens the whole sentence, often as the title/subject of a book, article, or report, or to shift to a new topic — 关于这个问题，我有一些想法 (regarding this question, I have some thoughts); it can't easily sit after the subject. 对于 + Topic can also open the sentence, but — unlike 关于 — it can also come AFTER the subject, right before the comment: 我对于这个结果很满意 (I am quite satisfied with this result) or 对于这个结果，我很满意 (regarding this result, I'm quite satisfied) — both are fine, since 对于 attaches an attitude/reaction (satisfied, interested, concerned) to a topic, which 关于 rarely does. The deciding question: does the subject have a reaction, opinion, or attitude toward the topic (→对于, and it can follow the subject), or am I simply announcing/shifting to a new topic before saying anything about it (→关于, always sentence-initial)?",id:"关于 dan 对于 sama-sama kira-kira berarti 'tentang, mengenai', memperkenalkan topik yang akan dibahas kalimat itu, tapi keduanya menempel dengan cara berbeda. 关于 + Topik hampir selalu membuka seluruh kalimat, sering sebagai judul/subjek buku, artikel, atau laporan, atau untuk beralih ke topik baru — 关于这个问题，我有一些想法 (mengenai pertanyaan ini, saya punya beberapa pemikiran); 关于 tidak mudah diletakkan setelah subjek. 对于 + Topik juga bisa membuka kalimat, tapi — berbeda dengan 关于 — juga bisa muncul SETELAH subjek, tepat sebelum komentarnya: 我对于这个结果很满意 (saya cukup puas dengan hasil ini) atau 对于这个结果，我很满意 (mengenai hasil ini, saya cukup puas) — keduanya benar, karena 对于 melekatkan sikap/reaksi (puas, tertarik, khawatir) pada suatu topik, yang jarang dilakukan 关于. Pertanyaan penentu: apakah subjeknya punya reaksi, pendapat, atau sikap terhadap topik itu (→对于, dan bisa mengikuti subjek), atau saya hanya mengumumkan/beralih ke topik baru sebelum mengatakan apa pun tentangnya (→关于, selalu di awal kalimat)?"},examples:[{s:"关于这个问题，我有一些想法。",p:"guān yú zhè ge wèn tí, wǒ yǒu yì xiē xiǎng fǎ",en:"Regarding this question, I have some thoughts.",id:"Mengenai pertanyaan ini, saya punya beberapa pemikiran."},{s:"我对于这个结果很满意。",p:"wǒ duì yú zhè ge jié guǒ hěn mǎn yì",en:"I'm quite satisfied with this result.",id:"Saya cukup puas dengan hasil ini."},{s:"关于这次考试，老师对于大家的成绩都很满意。",p:"guān yú zhè cì kǎo shì, lǎo shī duì yú dà jiā de chéng jì dōu hěn mǎn yì",en:"Regarding this exam, the teacher is quite satisfied with everyone's results.",id:"Mengenai ujian kali ini, guru cukup puas dengan nilai semua orang."}],mistake:{wrong:"我关于这个结果很满意。",right:"我对于这个结果很满意。",note:{en:"Expressing your own attitude or reaction toward a topic (satisfied, worried, interested) needs 对于, which can follow the subject — 关于 almost always opens the sentence and doesn't attach a personal reaction this way.",id:"Mengungkapkan sikap atau reaksimu sendiri terhadap suatu topik (puas, khawatir, tertarik) membutuhkan 对于, yang bisa mengikuti subjek — 关于 hampir selalu membuka kalimat dan tidak melekatkan reaksi pribadi seperti ini."}}}];a.s(["GRAMMAR",0,e,"GRAMMAR_FN_ORDER",0,["questions","time","describing","comparing","connecting","past","ability","objects"],"grammarById",0,a=>e.find(e=>e.id===a)])}]);